import { useCallback, useEffect, useState } from "react";

type Options = {
  count: number;
  /** Dwell per slide, in ms. */
  interval: number;
  /** Autoplay master switch from the toggle. */
  autoplay: boolean;
};

/**
 * Slide index plus autoplay lifecycle.
 *
 * Autoplay stops in three situations, all of which matter:
 *  - the visitor is interacting (hover or keyboard focus inside the carousel),
 *  - the tab is hidden, so a backgrounded page does not silently burn through
 *    every slide and land the visitor somewhere arbitrary on return,
 *  - the visitor prefers reduced motion, where an auto-advancing carousel is a
 *    genuine accessibility problem rather than a stylistic one.
 *
 * The timer keys off `index`, so manual navigation restarts the dwell — a
 * visitor who clicks to slide 3 gets a full interval to read it, not whatever
 * remained of slide 2's.
 */
export function useCarousel({ count, interval, autoplay }: Options) {
  const [index, setIndex] = useState(0);
  const [interacting, setInteracting] = useState(false);
  const [hidden, setHidden] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(false);

  const goTo = useCallback(
    (next: number) => {
      if (count < 1) return;
      setIndex(((next % count) + count) % count);
    },
    [count]
  );

  const next = useCallback(() => goTo(index + 1), [goTo, index]);
  const previous = useCallback(() => goTo(index - 1), [goTo, index]);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReducedMotion(query.matches);

    sync();
    query.addEventListener("change", sync);
    return () => query.removeEventListener("change", sync);
  }, []);

  useEffect(() => {
    const sync = () => setHidden(document.hidden);

    sync();
    document.addEventListener("visibilitychange", sync);
    return () => document.removeEventListener("visibilitychange", sync);
  }, []);

  const playing = autoplay && !interacting && !hidden && !reducedMotion && count > 1;

  useEffect(() => {
    if (!playing) return;

    const timer = setTimeout(() => {
      setIndex((current) => (current + 1) % count);
    }, interval);

    return () => clearTimeout(timer);
  }, [playing, interval, count, index]);

  return {
    index,
    goTo,
    next,
    previous,
    /** Bind to hover and focus handlers on the carousel root. */
    setInteracting,
    playing,
  };
}

export default useCarousel;
