import React from "react";
import { Link } from "gatsby";
import { LuArrowRight } from "react-icons/lu";

import type { BenefitsTemplate } from "../../templates/benefits/default-template";
import useInView from "../shared/useInView";
import type { Benefit } from "./types";

export type BenefitsProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: BenefitsTemplate;
  benefits: Benefit[];
  /** Section heading. Passed in so this reuses the shared SectionTitle. */
  heading?: React.ReactNode;
  footer?: { title: string; cta: { label: string; href: string } };
  /**
   * Explains the asterisk on any `qualified` card. Rendered under the grid,
   * once, rather than repeated on every card that carries the mark.
   */
  footnote?: string;
  enabled?: boolean;
};

/**
 * The What You Get amenity grid.
 *
 * One card component, one uniform grid, everything visible at rest. Hover only
 * adds emphasis, so a touch device loses no information.
 */
export default function Benefits({
  template,
  benefits,
  heading,
  footer,
  footnote,
  enabled = true,
}: BenefitsProps) {
  const { ref, inView } = useInView<HTMLElement>();

  if (!enabled || benefits.length === 0) return null;

  const root = template.rootClass;

  return (
    <section ref={ref} className={`${root}${inView ? ` ${root}--in` : ""}`}>
      <style>{template.css}</style>
      <noscript>
        <style>{template.noscriptCss}</style>
      </noscript>

      <div className={`${root}__panel`} aria-hidden="true" />

      <div className={`${root}__inner`}>
        {heading ? <div className={`${root}__heading`}>{heading}</div> : null}

        <ul className={`${root}__grid`}>
          {benefits.map((benefit, index) => (
            <li
              key={benefit.id}
              className={`${root}__tile`}
              style={{ ["--kr-ben-delay" as string]: `${index * template.timing.stagger}ms` }}
            >
              <span className={`${root}__figure`}>
                <img
                  className={`${root}__image`}
                  src={benefit.image}
                  srcSet={benefit.imageSrcSet}
                  sizes={benefit.imageSrcSet ? "(max-width: 780px) 46vw, 20vw" : undefined}
                  alt={benefit.imageAlt}
                  style={
                    benefit.imagePosition
                      ? { objectPosition: benefit.imagePosition }
                      : undefined
                  }
                  loading={index < 5 ? "eager" : "lazy"}
                  decoding="async"
                />
                <p className={`${root}__number`}>{benefit.number}</p>
              </span>

              <div className={`${root}__body`}>
                <h3 className={`${root}__title`}>
                  {benefit.title}
                  {benefit.qualified ? (
                    <>
                      {/* Decorative: the asterisk is a pointer to the note
                          below, and the note is read in its own right. Read
                          aloud it would just be "asterisk". */}
                      <span className={`${root}__mark`} aria-hidden="true">
                        *
                      </span>
                      <span className="kr-sr-only"> — at select properties</span>
                    </>
                  ) : null}
                </h3>
                <span className={`${root}__rule`} aria-hidden="true" />
                <p className={`${root}__description`}>{benefit.description}</p>
              </div>
            </li>
          ))}
        </ul>

        {footnote ? <p className={`${root}__footnote`}>{footnote}</p> : null}

        {footer ? (
          <div className={`${root}__footer`}>
            <p className={`${root}__footer-title`}>{footer.title}</p>
            <Link className="kr-btn kr-btn--dark" to={footer.cta.href}>
              {footer.cta.label}
              <LuArrowRight size={14} strokeWidth={1.75} aria-hidden="true" />
            </Link>
          </div>
        ) : null}
      </div>
    </section>
  );
}
