import React from "react";
import { Link } from "gatsby";
import { LuArrowRight } from "react-icons/lu";

import type {
  HowItWorksLabels,
  HowItWorksTemplate,
} from "../../templates/how-it-works/default-template";
import useInView from "../shared/useInView";
import type { ProcessStep } from "./types";
import useJourney from "./useJourney";

export type HowItWorksProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: HowItWorksTemplate;
  steps: ProcessStep[];
  /** Section heading. Passed in so this reuses the shared SectionTitle. */
  heading?: React.ReactNode;
  /** Closing prompt beneath the timeline. */
  footer?: {
    title: string;
    cta: { label: string; href: string };
    secondary?: { label: string; href: string };
  };
  enabled?: boolean;
  labels?: Partial<HowItWorksLabels>;
};

/**
 * The renter journey: Find → View → Apply → Move In.
 *
 * The sequence is decorative. Every step's number, title, description and link
 * is in the DOM from the first render, so the process reads correctly with
 * JavaScript disabled, with animation disabled, and to a screen reader — the
 * animation only controls when each becomes visually prominent.
 */
export default function HowItWorks({
  template,
  steps,
  heading,
  footer,
  enabled = true,
  labels: labelOverrides,
}: HowItWorksProps) {
  const labels = { ...template.labels, ...labelOverrides };
  const { ref, inView } = useInView<HTMLElement>();
  const { step, fill, running, complete } = useJourney({
    count: steps.length,
    active: inView,
    lead: template.timing.lead,
    stagger: template.timing.stagger,
  });

  if (!enabled || steps.length === 0) return null;

  const root = template.rootClass;
  const size = template.layout.circleSize;

  return (
    <section
      ref={ref}
      className={`${root}${running ? ` ${root}--running` : ""}${
        complete ? ` ${root}--complete` : ""
      }`}
      style={{ ["--kr-hiw-fill" as string]: String(fill) }}
    >
      <style>{template.css}</style>
      <noscript>
        <style>{template.noscriptCss}</style>
      </noscript>

      <div className={`${root}__inner`}>
        {heading ? <div className={`${root}__heading`}>{heading}</div> : null}

        <div className={`${root}__timeline`}>
          <div className={`${root}__track`} aria-hidden="true">
            <div className={`${root}__track-fill`} />
            <span className={`${root}__dot`} />
          </div>

          <ol className={`${root}__steps`}>
            {steps.map((item, index) => {
              const Icon = item.icon;
              const active = index < step;

              return (
                <li
                  key={item.number}
                  className={`${root}__step ${root}__step--${item.variant}${
                    active ? ` ${root}__step--active` : ""
                  }`}
                >
                  <span className={`${root}__circle`}>
                    <span className={`${root}__icon`} aria-hidden="true">
                      <Icon size={Math.round(size * 0.32)} strokeWidth={1.4} />
                    </span>
                  </span>

                  <div className={`${root}__body`}>
                    <p className={`${root}__number`}>
                      {labels.stepPrefix} {item.number}
                    </p>
                    <h3 className={`${root}__title`}>{item.title}</h3>
                    <p className={`${root}__description`}>{item.description}</p>

                    {item.cta ? (
                      <Link className={`${root}__cta`} to={item.cta.href}>
                        {item.cta.label}
                        <span className={`${root}__cta-arrow`} aria-hidden="true">
                          <LuArrowRight size={13} strokeWidth={1.75} />
                        </span>
                      </Link>
                    ) : item.welcome ? (
                      <span className={`${root}__welcome`}>{labels.welcome}</span>
                    ) : null}
                  </div>
                </li>
              );
            })}
          </ol>
        </div>

        {footer ? (
          <div className={`${root}__footer`}>
            <p className={`${root}__footer-title`}>{footer.title}</p>
            <Link className="kr-btn kr-btn--gold" to={footer.cta.href}>
              {footer.cta.label}
              <LuArrowRight size={14} strokeWidth={1.75} aria-hidden="true" />
            </Link>
            {footer.secondary ? (
              <Link className={`${root}__footer-link`} to={footer.secondary.href}>
                {footer.secondary.label}
              </Link>
            ) : null}
          </div>
        ) : null}
      </div>
    </section>
  );
}
