import React from "react";
import { FiChevronDown, FiHome, FiMapPin, FiSearch, FiSliders } from "react-icons/fi";

import type { HeroLabels } from "../../templates/hero/default-template";
import type { PropertyTypeOption } from "./types";

export type PropertySearchProps = {
  labels: HeroLabels;
  types: PropertyTypeOption[];
  /** Where the search resolves. A plain GET so it works without JavaScript. */
  action: string;
  /** Render the extra-filters button. Hidden on mobile by the stylesheet. */
  showFilter?: boolean;
  onFilterClick?: () => void;
};

/**
 * The hero property search.
 *
 * A real form posting GET to `action`, with named fields, so the search still
 * works if JavaScript never arrives and so results land on a linkable,
 * shareable URL rather than in component state.
 *
 * The field names are the ones the properties search page reads, so pressing
 * Search here arrives there with the filters already applied and the chips
 * already showing. Nobody should have to enter the same search twice.
 */
export default function PropertySearch({
  labels,
  types,
  action,
  showFilter = true,
  onFilterClick,
}: PropertySearchProps) {
  return (
    <form className="kr-search" action={action} method="get" role="search">
      <div className="kr-search__field kr-search__field--type">
        <span className="kr-search__icon" aria-hidden="true">
          <FiHome size={16} />
        </span>

        <label className="kr-sr-only" htmlFor="kr-search-beds">
          {labels.searchTypeLabel}
        </label>
        <select
          id="kr-search-beds"
          name="bedrooms"
          className="kr-search__select"
          defaultValue=""
        >
          <option value="">{labels.searchTypeLabel}</option>
          {types.map((type) => (
            <option key={type.value} value={type.value}>
              {type.label}
            </option>
          ))}
        </select>

        <span className="kr-search__caret" aria-hidden="true">
          <FiChevronDown size={15} />
        </span>
      </div>

      <span className="kr-search__divider" aria-hidden="true" />

      <div className="kr-search__field">
        <span className="kr-search__icon" aria-hidden="true">
          <FiMapPin size={16} />
        </span>

        <label className="kr-sr-only" htmlFor="kr-search-location">
          {labels.searchQueryLabel}
        </label>
        <input
          id="kr-search-location"
          name="location"
          type="search"
          className="kr-search__input"
          placeholder={labels.searchPlaceholder}
          autoComplete="off"
        />
      </div>

      {showFilter ? (
        <button
          type="button"
          className="kr-search__filter"
          aria-label={labels.filterLabel}
          onClick={onFilterClick}
        >
          <FiSliders size={16} />
        </button>
      ) : null}

      <button type="submit" className="kr-btn kr-btn--gold kr-search__submit">
        <FiSearch size={15} aria-hidden="true" />
        {labels.searchSubmit}
      </button>
    </form>
  );
}
