// Durations in milliseconds.
//
// The brief is explicit that the reference carousel makes you wait. The
// information should land almost as fast as the image: each element runs a
// 300ms animation, offset 100ms apart, so the title finishes at 300ms, the
// description at 400ms and the CTA at 500ms — the top of each target window.
const timing = {
  /** Crossfade between photographs. */
  fade: 900,

  /** Content stagger. */
  titleDelay: 0,
  descriptionDelay: 100,
  ctaDelay: 200,
  contentDuration: 300,

  /** Eyebrow leads the title very slightly so the block reads top-down. */
  eyebrowDelay: 0,

  /**
   * Ken Burns. Deliberately longer than one autoplay cycle plus the fade, so
   * the zoom never reaches its end and visibly stalls before the slide changes.
   */
  zoom: 9000,

  /** Autoplay dwell, measured from the moment a slide becomes active. */
  autoplay: 6000,
};

export default timing;
