// Structure and responsive sizing. No colour.
const layout = {
  maxWidth: 1280,

  iconSize: 26,
  /** Consistent stroke across every icon — the brief values this over variety. */
  iconStroke: 1.25,

  /* Hairline ring around each icon. Light enough not to read as a card, but
     it gives the column a fixed anchor point so the four align optically. */
  ringSize: 72,
  ringSizeCompact: 62,
  ringBorder: 1,

  /** Hairline between columns. */
  separatorWidth: 1,
  separatorHeight: "68%",
  /** Length of the gold segment overlaid on the hairline. */
  separatorAccentHeight: 26,

  /** Lift on hover. Deliberately small. */
  hoverLift: -2,

  /**
   * 4 across, then 2x2 all the way down. No single-column breakpoint: four
   * short statistics stacked vertically turns a compact trust cue into a long
   * scroll, and 2x2 stays comfortably readable at 320px.
   */
  twoUpBelow: 900,
};

export default layout;
