// Styling for the What You Get amenity grid.
//
// Structure follows the reference: a uniform grid of cards, each a photograph
// with a content box directly beneath it, every card the same size.
//
// Two decisions worth stating:
//
// 1. The dark card is a HOVER state, not a fixed one. In the reference exactly
//    one card is highlighted, which reads as the hovered card frozen in a
//    screenshot. So every card takes the treatment on hover and none wears it
//    permanently — otherwise one amenity looks arbitrarily more important.
//
// 2. Card heights are equal by construction: fixed-ratio media box, full-height
//    flex column, body flexes to fill. A longer description cannot make one
//    card taller than its neighbours.

import template1 from "./template-1";

export type BenefitsLabels = Record<string, never>;

export type BenefitsTemplate = {
  css: string;
  noscriptCss: string;
  rootClass: string;
  timing: typeof template1.timing;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-ben {
  position: relative;
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
  overflow: hidden;
}
.kr-ben__inner {
  position: relative;
  z-index: 1;
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
}
.kr-ben__heading { margin-bottom: ${spacing.headingGap}px; }

/* Charcoal band behind the lower part of the grid only, so the section stays
   predominantly white while the cards gain something to sit against. */
.kr-ben__panel {
  position: absolute;
  left: 0;
  right: 0;
  bottom: ${spacing.sectionBottom}px;
  height: ${layout.panelHeight};
  background: ${color.panel};
  pointer-events: none;
}
.kr-ben__panel::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(90deg, ${color.panelLines} 0 1px, transparent 1px 120px),
    repeating-linear-gradient(0deg, ${color.panelLines} 0 1px, transparent 1px 120px);
}

/* ── uniform grid, five across ────────────────────────── */
.kr-ben__grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  align-items: stretch;
  gap: ${spacing.gridGap}px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.kr-ben__tile {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  border: 1px solid ${color.tileBorder};
  border-radius: ${layout.radius}px;
  overflow: hidden;
  opacity: 0;
  transform: translateY(20px);
  transition:
    opacity ${timing.tile}ms ${ease} var(--kr-ben-delay, 0ms),
    transform ${timing.tile}ms ${ease} var(--kr-ben-delay, 0ms),
    border-color ${timing.hover}ms ${ease},
    box-shadow ${timing.hover}ms ${ease};
}
.kr-ben--in .kr-ben__tile { opacity: 1; transform: translateY(0); }

.kr-ben--in .kr-ben__tile:hover,
.kr-ben--in .kr-ben__tile:focus-within {
  border-color: ${color.hoverBorder};
  box-shadow: ${color.hoverShadow};
  transform: translateY(${layout.lift}px);
  transition-delay: 0ms;
}

.kr-ben__link { position: absolute; inset: 0; z-index: 3; }
.kr-ben__tile:focus-within { outline: 2px solid ${color.focus}; outline-offset: 2px; }
.kr-ben__link:focus-visible { outline: none; }

/* ── photograph, on top ───────────────────────────────── */
.kr-ben__figure {
  position: relative;
  display: block;
  aspect-ratio: ${layout.tileAspect};
  background: ${color.mediaPlaceholder};
  overflow: hidden;
  flex-shrink: 0;
}
.kr-ben__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform ${timing.zoom}ms ${ease};
}
.kr-ben__tile:hover .kr-ben__image { transform: scale(${layout.imageZoom}); }

/* Gold number chip riding the corner of the photograph. */
.kr-ben__number {
  position: absolute;
  left: 0;
  bottom: 0;
  z-index: 1;
  margin: 0;
  padding: ${spacing.numberPaddingY}px ${spacing.numberPaddingX}px;
  background: ${color.numberBackground};
  color: ${color.numberText};
  font-family: ${typography.numberFamily};
  font-size: ${typography.numberSize}px;
  font-weight: ${typography.numberWeight};
  letter-spacing: ${typography.numberTracking};
  line-height: 1;
}

/* ── content box, below ───────────────────────────────── */
.kr-ben__body {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: ${spacing.tilePadding}px;
  background: ${color.bodyBackground};
  transition: background-color ${timing.hover}ms ${ease};
}
/* The highlight — applied to whichever card is hovered. */
.kr-ben__tile:hover .kr-ben__body,
.kr-ben__tile:focus-within .kr-ben__body {
  background: ${color.hoverBodyBackground};
}

.kr-ben__title {
  margin: 0;
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
  line-height: ${typography.titleLeading};
  transition: color ${timing.hover}ms ${ease};
}
.kr-ben__tile:hover .kr-ben__title,
.kr-ben__tile:focus-within .kr-ben__title { color: ${color.hoverTitle}; }

.kr-ben__rule {
  display: block;
  width: ${layout.ruleWidth}px;
  height: 2px;
  margin: ${spacing.ruleGap}px 0 0;
  background: ${color.rule};
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform ${timing.rule}ms ${ease};
}
.kr-ben__tile:hover .kr-ben__rule,
.kr-ben__tile:focus-within .kr-ben__rule { transform: scaleX(1); }

.kr-ben__description {
  margin: ${spacing.descriptionGap}px 0 0;
  color: ${color.description};
  font-family: ${typography.descriptionFamily};
  font-size: ${typography.descriptionSize}px;
  font-weight: ${typography.descriptionWeight};
  line-height: ${typography.descriptionLeading};
  transition: color ${timing.hover}ms ${ease};
}
.kr-ben__tile:hover .kr-ben__description,
.kr-ben__tile:focus-within .kr-ben__description { color: ${color.hoverDescription}; }

/* ── footer CTA ───────────────────────────────────────── */
/* The asterisk on a card whose amenity only some properties have. Gold, so it
   reads as a deliberate mark rather than a typo, and small enough not to
   compete with the title it follows. */
.kr-ben__mark {
  margin-left: 3px;
  color: ${color.rule};
  font-weight: 700;
}

/* Said once, under the grid, rather than repeated on every card carrying the
   mark. Centred with the footer below it so the two read as one closing note. */
.kr-ben__footnote {
  margin: 26px 0 0;
  color: ${color.description};
  font-size: 13px;
  text-align: center;
}

.kr-ben__footer {
  margin-top: ${spacing.footerGap}px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 22px;
  text-align: center;
}
.kr-ben__footer-title {
  margin: 0;
  color: ${color.title};
  font-family: ${typography.footerTitleFamily};
  font-size: ${typography.footerTitleSize};
  font-weight: ${typography.footerTitleWeight};
  letter-spacing: -0.03em;
}

/* ── responsive ───────────────────────────────────────── */
@media (max-width: ${layout.fiveUpFrom - 1}px) {
  .kr-ben__grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: ${layout.threeUpFrom - 1}px) {
  .kr-ben { padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px; }
  .kr-ben__inner { padding: 0 ${spacing.gutterCompact}px; }
  .kr-ben__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: ${spacing.gridGapCompact}px;
  }
  .kr-ben__body { padding: ${spacing.tilePaddingCompact}px; }
}
@media (max-width: ${layout.twoUpFrom - 1}px) {
  .kr-ben__panel { display: none; }
  .kr-ben__grid { grid-template-columns: minmax(0, 1fr); }
  .kr-ben__footer { margin-top: 44px; flex-direction: column; gap: 18px; }
}

/* Touch devices have no hover, so the rule is shown at rest instead of being
   a detail only a mouse user ever sees. */
@media (hover: none) {
  .kr-ben__rule { transform: scaleX(1); }
}

@media (prefers-reduced-motion: reduce) {
  .kr-ben__tile,
  .kr-ben__image,
  .kr-ben__body,
  .kr-ben__title,
  .kr-ben__description,
  .kr-ben__rule {
    transition: none;
  }
  .kr-ben__tile { opacity: 1; transform: none; }
  .kr-ben--in .kr-ben__tile:hover { transform: none; }
  .kr-ben__tile:hover .kr-ben__image { transform: none; }
  .kr-ben__rule { transform: scaleX(1); }
}
`;

const noscriptCss = `
.kr-ben__tile { opacity: 1; transform: none; }
`;

const template: BenefitsTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-ben",
  timing,
};

export default template;
