import { useEffect, useState } from "react";

type Options = {
  count: number;
  /** Start the sequence — normally the section's in-view flag. */
  active: boolean;
  lead: number;
  stagger: number;
};

/**
 * Advances the journey one step at a time once the section is on screen.
 *
 * Returns how many steps have activated. The caller derives the track fill
 * from that single number, so the line, the travelling dot and the circles
 * can never disagree about where the journey has got to.
 *
 * Under prefers-reduced-motion the whole journey is marked complete
 * immediately: the point of the section is the four stages, and someone who
 * has asked for less motion should still see all four, just not travel through
 * them.
 */
export function useJourney({ count, active, lead, stagger }: Options) {
  const [step, setStep] = useState(0);

  useEffect(() => {
    if (!active || count === 0) return;

    const reduced =
      typeof window !== "undefined" &&
      typeof window.matchMedia === "function" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    if (reduced) {
      setStep(count);
      return;
    }

    const timers: Array<ReturnType<typeof setTimeout>> = [];
    for (let i = 0; i < count; i++) {
      timers.push(setTimeout(() => setStep(i + 1), lead + i * stagger));
    }

    return () => timers.forEach(clearTimeout);
  }, [active, count, lead, stagger]);

  /** 0–1 along the track. Step 1 sits at the start, step `count` at the end. */
  const fill = count > 1 ? Math.min(Math.max((step - 1) / (count - 1), 0), 1) : 0;

  return {
    step,
    fill,
    running: step > 0 && step < count,
    complete: step >= count && count > 0,
  };
}

export default useJourney;
