// Styling for the final conversion CTA.
//
// The overlay is the decision that matters. A flat dark wash over the whole
// frame would make the photograph pointless; instead two gradients run
// left-to-right and bottom-up, so the text side is dark enough for white type
// at full contrast while the right side stays close to the original image.
//
// The section also does the transition into the footer: it is the warm, bright
// beat, and the footer immediately below is the dark one.

import template1 from "./template-1";

export type FinalCtaTemplate = {
  css: string;
  noscriptCss: string;
  rootClass: string;
  timing: typeof template1.timing;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-cta {
  position: relative;
  min-height: ${layout.height}px;
  display: flex;
  align-items: center;
  background: ${color.base};
  overflow: hidden;
  isolation: isolate;
}

.kr-cta__media { position: absolute; inset: 0; z-index: 0; }
.kr-cta__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transform: scale(1);
  transition: transform ${timing.zoom}ms linear;
}
/* Starts once the section is on screen, so it is never mid-drift on arrival. */
.kr-cta--in .kr-cta__image { transform: scale(${layout.zoomTo}); }

.kr-cta__scrim {
  position: absolute;
  inset: 0;
  z-index: 1;
  background-image: ${color.scrim}, ${color.scrimBase};
  pointer-events: none;
}

.kr-cta__inner {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
}
.kr-cta__content { max-width: ${layout.contentMaxWidth}px; }

/* Gold rule leading the eyebrow — the site's recurring accent. */
.kr-cta__rule {
  display: block;
  width: ${layout.ruleWidth}px;
  height: 2px;
  margin: 0 0 ${spacing.ruleGap}px;
  background: ${color.rule};
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform ${timing.eyebrow}ms ${ease} ${timing.eyebrowDelay}ms;
}
.kr-cta--in .kr-cta__rule { transform: scaleX(1); }

.kr-cta__eyebrow {
  margin: 0 0 ${spacing.eyebrowGap}px;
  color: ${color.eyebrow};
  font-family: ${typography.eyebrowFamily};
  font-size: ${typography.eyebrowSize}px;
  font-weight: ${typography.eyebrowWeight};
  letter-spacing: ${typography.eyebrowTracking};
  text-transform: uppercase;
}
.kr-cta__title {
  margin: 0 0 ${spacing.titleGap}px;
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
  line-height: ${typography.titleLeading};
}
.kr-cta__description {
  margin: 0 0 ${spacing.descriptionGap}px;
  max-width: 52ch;
  color: ${color.description};
  font-family: ${typography.descriptionFamily};
  font-size: ${typography.descriptionSize};
  font-weight: ${typography.descriptionWeight};
  line-height: ${typography.descriptionLeading};
}

.kr-cta__eyebrow,
.kr-cta__title,
.kr-cta__description,
.kr-cta__actions {
  opacity: 0;
  transform: translateY(16px);
  transition:
    opacity var(--kr-cta-duration) ${ease} var(--kr-cta-delay),
    transform var(--kr-cta-duration) ${ease} var(--kr-cta-delay);
}
.kr-cta__eyebrow     { --kr-cta-duration: ${timing.eyebrow}ms;     --kr-cta-delay: ${timing.eyebrowDelay}ms; }
.kr-cta__title       { --kr-cta-duration: ${timing.title}ms;       --kr-cta-delay: ${timing.titleDelay}ms; }
.kr-cta__description { --kr-cta-duration: ${timing.description}ms; --kr-cta-delay: ${timing.descriptionDelay}ms; }
.kr-cta__actions     { --kr-cta-duration: ${timing.actions}ms;     --kr-cta-delay: ${timing.actionsDelay}ms; }

.kr-cta--in .kr-cta__eyebrow,
.kr-cta--in .kr-cta__title,
.kr-cta--in .kr-cta__description,
.kr-cta--in .kr-cta__actions {
  opacity: 1;
  transform: none;
}

.kr-cta__actions {
  display: flex;
  flex-wrap: wrap;
  gap: ${spacing.buttonGap}px;
}

/* Outline button on photography: the shared kr-btn--outline is gold-on-white,
   which would disappear here, so this variant is white-on-image. */
.kr-cta__secondary {
  border-color: ${color.secondaryBorder};
  color: ${color.secondaryText};
  background: transparent;
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
}
.kr-cta__secondary:hover {
  background: ${color.secondaryHoverBackground};
  border-color: ${color.secondaryHoverBackground};
  color: ${color.secondaryHoverText};
}
.kr-cta__secondary:focus-visible { outline-color: ${color.focus}; }

/* ── responsive ───────────────────────────────────────── */
@media (max-width: 980px) {
  .kr-cta { min-height: ${layout.heightTablet}px; }
  .kr-cta__inner { padding: 0 ${spacing.gutterCompact}px; }
}
@media (max-width: 640px) {
  .kr-cta { min-height: ${layout.heightMobile}px; }
  /* Narrow screens leave no clear right-hand side, so the wash evens out. */
  .kr-cta__scrim {
    background-image:
      linear-gradient(to right, rgba(31,35,40,.90) 0%, rgba(31,35,40,.72) 100%),
      ${color.scrimBase};
  }
}
@media (max-width: ${layout.stackButtonsBelow}px) {
  .kr-cta__actions { flex-direction: column; align-items: stretch; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-cta__image { transition: none; }
  .kr-cta--in .kr-cta__image { transform: none; }
  .kr-cta__rule { transform: scaleX(1); transition: none; }
  .kr-cta__eyebrow,
  .kr-cta__title,
  .kr-cta__description,
  .kr-cta__actions {
    opacity: 1;
    transform: none;
    transition: none;
  }
}
`;

const noscriptCss = `
.kr-cta__rule { transform: scaleX(1); }
.kr-cta__eyebrow,
.kr-cta__title,
.kr-cta__description,
.kr-cta__actions { opacity: 1; transform: none; }
`;

const template: FinalCtaTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-cta",
  timing,
};

export default template;
