// Styling for the How It Works renter-journey timeline.
//
// The connecting track is the centrepiece, so it is one element spanning the
// whole row rather than four disconnected cards with borders between them.
//
// One number drives the whole animation: `--kr-hiw-fill`, a unitless 0–1 that
// React sets as the sequence advances. The filled track reads it as
// scaleX(var(...)) and the travelling dot reads it as left: calc(var(...) *
// 100%), so the dot cannot drift out of sync with the line — they are the same
// value rendered two ways. The vertical mobile layout reuses the same variable
// through scaleY and top.

import template1 from "./template-1";

export type HowItWorksLabels = {
  /** Prefix before each step number, e.g. "Step". */
  stepPrefix: string;
  /** Small gold micro-label on the final step. */
  welcome: string;
};

export type HowItWorksTemplate = {
  css: string;
  noscriptCss: string;
  rootClass: string;
  timing: typeof template1.timing;
  layout: typeof template1.layout;
  labels: HowItWorksLabels;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const labels: HowItWorksLabels = {
  stepPrefix: "Step",
  welcome: "Welcome Home",
};

const css = `
.kr-hiw {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
}
.kr-hiw__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
}
.kr-hiw__heading { margin-bottom: ${spacing.headingGap}px; }

/* ── track ────────────────────────────────────────────────
   Spans the centres of the first and last circles, so it never pokes out
   past the row. */
.kr-hiw__timeline {
  position: relative;
}
.kr-hiw__track {
  position: absolute;
  top: ${layout.circleSize / 2}px;
  left: calc(100% / 8);
  right: calc(100% / 8);
  height: ${layout.trackThickness}px;
  background: ${color.track};
  transform: translateY(-50%);
}
.kr-hiw__track-fill {
  position: absolute;
  inset: 0;
  background: ${color.trackFill};
  transform-origin: left center;
  transform: scaleX(var(--kr-hiw-fill, 0));
  transition: transform ${timing.fill}ms linear;
}
/* Rides the leading edge of the fill. */
.kr-hiw__dot {
  position: absolute;
  top: 50%;
  left: calc(var(--kr-hiw-fill, 0) * 100%);
  width: ${layout.dotSize}px;
  height: ${layout.dotSize}px;
  margin: -${layout.dotSize / 2}px 0 0 -${layout.dotSize / 2}px;
  border-radius: 50%;
  background: ${color.trackFill};
  opacity: 0;
  transition: left ${timing.fill}ms linear, opacity .3s ${ease};
}
.kr-hiw--running .kr-hiw__dot { opacity: 1; }
.kr-hiw--complete .kr-hiw__dot { opacity: 0; }

/* ── steps ────────────────────────────────────────────── */
.kr-hiw__steps {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 24px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.kr-hiw__step {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

/* ── circle ───────────────────────────────────────────── */
.kr-hiw__circle {
  position: relative;
  width: ${layout.circleSize}px;
  height: ${layout.circleSize}px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: ${layout.circleBorderWidth}px solid ${color.circleBorder};
  border-radius: 50%;
  background: ${color.circleBackground};
  color: ${color.circleIcon};
  flex-shrink: 0;
  transition:
    background-color ${timing.circle}ms ${ease},
    border-color ${timing.circle}ms ${ease},
    color ${timing.circle}ms ${ease},
    transform ${timing.hover}ms ${ease};
}
/* Gold halo, drawn outside the circle so it never shifts layout. */
.kr-hiw__circle::before {
  content: "";
  position: absolute;
  inset: -${layout.ringWidth}px;
  border-radius: 50%;
  border: 1px solid ${color.ring};
  opacity: 0;
  transform: scale(.9);
  transition: opacity ${timing.circle}ms ${ease}, transform ${timing.circle}ms ${ease};
}
.kr-hiw__step--active .kr-hiw__circle {
  background: ${color.circleActiveBackground};
  border-color: ${color.circleActiveBackground};
  color: ${color.circleActiveIcon};
}
.kr-hiw__step--active .kr-hiw__circle::before { opacity: 1; transform: scale(1); }
.kr-hiw__step:hover .kr-hiw__circle { transform: scale(${layout.hoverScale}); }
.kr-hiw__step:hover .kr-hiw__circle::before {
  opacity: 1;
  transform: scale(1);
  border-color: ${color.ringStrong};
}

/* Tiny per-step icon motion. Barely noticeable, and only on hover. */
.kr-hiw__icon { display: inline-flex; transition: transform ${timing.hover}ms ${ease}; }
.kr-hiw__step--find:hover     .kr-hiw__icon { transform: translate(1.5px, -1.5px); }
.kr-hiw__step--view:hover     .kr-hiw__icon { transform: scale(1.09); }
.kr-hiw__step--apply:hover    .kr-hiw__icon { transform: translateY(-1.5px) rotate(-4deg); }
.kr-hiw__step--movein:hover   .kr-hiw__icon { transform: rotate(-12deg); }

/* ── step text ────────────────────────────────────────── */
.kr-hiw__body {
  margin-top: ${spacing.numberGap}px;
  opacity: 0;
  transform: translateY(12px);
  transition:
    opacity ${timing.text}ms ${ease},
    transform ${timing.text}ms ${ease};
}
.kr-hiw__step--active .kr-hiw__body { opacity: 1; transform: none; }

.kr-hiw__number {
  margin: 0 0 ${spacing.titleGap}px;
  color: ${color.stepNumber};
  font-family: ${typography.numberFamily};
  font-size: ${typography.numberSize}px;
  font-weight: ${typography.numberWeight};
  letter-spacing: ${typography.numberTracking};
  text-transform: uppercase;
}
.kr-hiw__title {
  margin: 0 0 ${spacing.descriptionGap}px;
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
  transition: color ${timing.hover}ms ${ease};
}
.kr-hiw__step:hover .kr-hiw__title { color: ${color.titleHover}; }

.kr-hiw__description {
  margin: 0;
  max-width: 30ch;
  color: ${color.description};
  font-family: ${typography.descriptionFamily};
  font-size: ${typography.descriptionSize}px;
  font-weight: ${typography.descriptionWeight};
  line-height: ${typography.descriptionLeading};
}
.kr-hiw__step { align-items: center; }
.kr-hiw__description { margin-left: auto; margin-right: auto; }

.kr-hiw__cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: ${spacing.ctaGap}px;
  color: ${color.cta};
  font-family: ${typography.ctaFamily};
  font-size: ${typography.ctaSize}px;
  font-weight: ${typography.ctaWeight};
  letter-spacing: ${typography.ctaTracking};
  text-transform: uppercase;
  text-decoration: none;
  transition: color ${timing.hover}ms ${ease};
}
.kr-hiw__cta:hover { color: ${color.ctaHover}; }
.kr-hiw__cta:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }
.kr-hiw__cta-arrow { transition: transform ${timing.hover}ms ${ease}; }
.kr-hiw__cta:hover .kr-hiw__cta-arrow { transform: translateX(4px); }

.kr-hiw__welcome {
  display: inline-block;
  margin-top: ${spacing.ctaGap}px;
  color: ${color.welcome};
  font-family: ${typography.ctaFamily};
  font-size: ${typography.ctaSize}px;
  font-weight: ${typography.ctaWeight};
  letter-spacing: ${typography.ctaTracking};
  text-transform: uppercase;
}

/* ── bottom CTA ───────────────────────────────────────── */
.kr-hiw__footer {
  margin-top: ${spacing.footerGap}px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 22px;
  text-align: center;
}
.kr-hiw__footer-title {
  margin: 0;
  color: ${color.title};
  font-family: ${typography.footerTitleFamily};
  font-size: ${typography.footerTitleSize};
  font-weight: ${typography.footerTitleWeight};
  letter-spacing: ${typography.titleTracking};
}
.kr-hiw__footer-link {
  color: ${color.footerText};
  font-family: ${typography.ctaFamily};
  font-size: ${typography.ctaSize}px;
  font-weight: ${typography.ctaWeight};
  letter-spacing: ${typography.ctaTracking};
  text-transform: uppercase;
  text-decoration: none;
  transition: color ${timing.hover}ms ${ease};
}
.kr-hiw__footer-link:hover { color: ${color.ctaHover}; }
.kr-hiw__footer-link:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }

/* ── vertical layout ──────────────────────────────────────
   Not a squeezed horizontal row: the rail moves to the left edge and each
   step becomes a row with its text beside the circle. */
@media (max-width: ${layout.verticalBelow}px) {
  .kr-hiw {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-hiw__inner { padding: 0 ${spacing.gutterCompact}px; }
  .kr-hiw__heading { margin-bottom: ${spacing.headingGapCompact}px; }

  .kr-hiw__track {
    top: ${layout.circleSizeMobile / 2}px;
    bottom: ${layout.circleSizeMobile / 2}px;
    left: ${layout.circleSizeMobile / 2}px;
    right: auto;
    width: ${layout.trackThickness}px;
    height: auto;
    transform: translateX(-50%);
  }
  .kr-hiw__track-fill {
    transform-origin: center top;
    transform: scaleY(var(--kr-hiw-fill, 0));
  }
  .kr-hiw__dot {
    left: 50%;
    top: calc(var(--kr-hiw-fill, 0) * 100%);
    transition: top ${timing.fill}ms linear, opacity .3s ${ease};
  }

  .kr-hiw__steps {
    grid-template-columns: minmax(0, 1fr);
    gap: ${spacing.stepGapVertical}px;
  }
  .kr-hiw__step {
    flex-direction: row;
    align-items: flex-start;
    gap: ${spacing.railGap}px;
    text-align: left;
  }
  .kr-hiw__circle {
    width: ${layout.circleSizeMobile}px;
    height: ${layout.circleSizeMobile}px;
  }
  .kr-hiw__body { margin-top: 6px; }
  .kr-hiw__description { max-width: none; margin-left: 0; margin-right: 0; }
  .kr-hiw__footer {
    margin-top: ${spacing.footerGapCompact}px;
    flex-direction: column;
    gap: 18px;
  }
}

@media (min-width: ${layout.verticalBelow + 1}px) and (max-width: 1120px) {
  .kr-hiw__circle {
    width: ${layout.circleSizeTablet}px;
    height: ${layout.circleSizeTablet}px;
  }
  .kr-hiw__track { top: ${layout.circleSizeTablet / 2}px; }
}

/* ── reduced motion ───────────────────────────────────────
   The journey must still be readable, so everything lands in its final state
   rather than simply not animating into existence. */
@media (prefers-reduced-motion: reduce) {
  .kr-hiw__track-fill { transform: scaleX(1); transition: none; }
  .kr-hiw__dot { display: none; }
  .kr-hiw__body { opacity: 1; transform: none; transition: none; }
  .kr-hiw__circle,
  .kr-hiw__icon,
  .kr-hiw__cta-arrow { transition: none; }
  .kr-hiw__step:hover .kr-hiw__circle { transform: none; }
  @media (max-width: ${layout.verticalBelow}px) {
    .kr-hiw__track-fill { transform: scaleY(1); }
  }
}
`;

/** Without JavaScript nothing activates, so show the completed journey. */
const noscriptCss = `
.kr-hiw__body { opacity: 1; transform: none; }
.kr-hiw__track-fill { transform: scaleX(1); }
.kr-hiw__dot { display: none; }
`;

const template: HowItWorksTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-hiw",
  timing,
  layout,
  labels,
};

export default template;
