import React from "react";
import { LuAward, LuBuilding2, LuKeyRound, LuMapPinned } from "react-icons/lu";

import template from "../../config/trust-strip--template";
import TrustStrip from "../../modules/trust-strip/TrustStrip";
import type { TrustStat } from "../../modules/trust-strip/types";
import trustStripEnabled from "../../toggles/trust-strip";
import SectionTitle from "../section-title/section-title";

/**
 * DEMO DATA — read before this goes live.
 *
 * Only "25+ Years of Experience" came from the client. The two figures below
 * are stand-ins so the strip reads as finished during review. They are NOT
 * client data and must be replaced.
 *
 * Set either back to "XX" to show a visible placeholder instead — the
 * component renders that muted and skips the count-up automatically.
 */
/** TODO(client): confirm the real figure. */
const DEMO_PROPERTIES_MANAGED = "180+";
/** TODO(client): confirm the real figure. */
const DEMO_COMMUNITIES_SERVED = "12";

/**
 * Trust statistics.
 *
 * Lucide icons via react-icons/lu — one family at one stroke weight, so the
 * four read as a set rather than four separately sourced glyphs.
 */
const stats: TrustStat[] = [
  {
    value: "25+",
    label: "Years of Experience",
    icon: LuAward,
  },
  {
    value: DEMO_PROPERTIES_MANAGED,
    label: "Properties Managed",
    icon: LuBuilding2,
  },
  {
    value: DEMO_COMMUNITIES_SERVED,
    label: "Communities Served",
    icon: LuMapPinned,
  },
  {
    value: "Dedicated",
    label: "Property Management",
    icon: LuKeyRound,
  },
];

/**
 * The homepage trust strip, configured.
 *
 * The heading is the shared SectionTitle primitive passed in as a slot, so the
 * strip reuses the site-wide title treatment rather than growing its own.
 */
export default function TrustStripX() {
  return (
    <TrustStrip
      template={template}
      enabled={trustStripEnabled}
      stats={stats}
      heading={
        <SectionTitle
          backgroundText="Trust"
          title="Experience You Can Count On"
          description="Professional property management backed by years of experience and a commitment to the communities we serve."
          align="center"
        />
      }
    />
  );
}
