// Styling for the FAQ.
//
// Editorial rather than boxed: rows separated by hairlines, no cards, no
// borders around each question.
//
// The expand animation uses the grid 0fr → 1fr technique, which animates to
// the answer's real height without JavaScript measuring it. Browsers without
// animatable grid rows fall back to a max-height transition, which is slightly
// less exact on easing but never clips content.

import template1 from "./template-1";

export type FaqLabels = {
  /** aria-label for the expand control, `{q}` replaced by the question. */
  toggle: string;
};

export type FaqTemplate = {
  css: string;
  noscriptCss: string;
  rootClass: string;
  timing: typeof template1.timing;
  labels: FaqLabels;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const labels: FaqLabels = { toggle: "{q}" };

const css = `
.kr-faq {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
}
.kr-faq__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
  display: grid;
  grid-template-columns: ${layout.introColumn} ${layout.listColumn};
  align-items: start;
  gap: ${spacing.columnGap}px;
}

/* ── intro column ─────────────────────────────────────── */
.kr-faq__lede {
  margin: ${spacing.ledeGap}px 0 0;
  color: ${color.lede};
  font-family: ${typography.ledeFamily};
  font-size: ${typography.ledeSize};
  font-weight: ${typography.ledeWeight};
  line-height: ${typography.ledeLeading};
}
.kr-faq__help { margin-top: ${spacing.helpGap}px; }
.kr-faq__help-title {
  margin: 0 0 ${spacing.helpTitleGap}px;
  color: ${color.helpTitle};
  font-family: ${typography.helpTitleFamily};
  font-size: ${typography.helpTitleSize}px;
  font-weight: ${typography.helpTitleWeight};
  letter-spacing: -0.02em;
}
.kr-faq__help-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: ${color.helpLink};
  font-family: ${typography.helpLinkFamily};
  font-size: ${typography.helpLinkSize}px;
  font-weight: ${typography.helpLinkWeight};
  letter-spacing: ${typography.helpLinkTracking};
  text-transform: uppercase;
  text-decoration: none;
  transition: color ${timing.hover}ms ${ease};
}
.kr-faq__help-link:hover { color: ${color.helpLinkHover}; }
.kr-faq__help-link:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }
.kr-faq__help-arrow { transition: transform ${timing.hover}ms ${ease}; }
.kr-faq__help-link:hover .kr-faq__help-arrow { transform: translateX(4px); }

/* ── list ─────────────────────────────────────────────── */
.kr-faq__list { margin: 0; padding: 0; list-style: none; }

.kr-faq__item {
  border-top: 1px solid ${color.divider};
  opacity: 0;
  transform: translateY(12px);
  transition:
    opacity ${timing.row}ms ${ease} var(--kr-faq-delay, 0ms),
    transform ${timing.row}ms ${ease} var(--kr-faq-delay, 0ms);
}
.kr-faq__item:last-child { border-bottom: 1px solid ${color.divider}; }
.kr-faq--in .kr-faq__item { opacity: 1; transform: none; }

/* The whole row is the control, so the hit area matches the visual row. */
.kr-faq__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  gap: ${spacing.numberGap}px;
  padding: ${spacing.rowPaddingY}px 0;
  border: 0;
  background: none;
  text-align: left;
  cursor: pointer;
  font: inherit;
}
.kr-faq__trigger:focus-visible {
  outline: 2px solid ${color.focus};
  outline-offset: 2px;
}

.kr-faq__number {
  flex-shrink: 0;
  color: ${color.number};
  font-family: ${typography.numberFamily};
  font-size: ${typography.numberSize}px;
  font-weight: ${typography.numberWeight};
  letter-spacing: ${typography.numberTracking};
}

.kr-faq__question {
  flex: 1;
  margin: 0;
  padding-right: ${spacing.questionGap}px;
  color: ${color.question};
  font-family: ${typography.questionFamily};
  font-size: ${typography.questionSize};
  font-weight: ${typography.questionWeight};
  letter-spacing: ${typography.questionTracking};
  line-height: ${typography.questionLeading};
  transition: color ${timing.hover}ms ${ease};
}
.kr-faq__trigger:hover .kr-faq__question,
.kr-faq__item--open .kr-faq__question { color: ${color.questionHover}; }

/* ── plus becoming a minus ─────────────────────────────── */
.kr-faq__toggle {
  position: relative;
  flex-shrink: 0;
  width: ${layout.toggleSize}px;
  height: ${layout.toggleSize}px;
}
.kr-faq__toggle::before,
.kr-faq__toggle::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: ${layout.toggleSpan}px;
  height: ${layout.toggleBar}px;
  margin: -${layout.toggleBar / 2}px 0 0 -${layout.toggleSpan / 2}px;
  background: ${color.toggle};
  transition:
    transform ${timing.toggle}ms ${ease},
    background-color ${timing.toggle}ms ${ease},
    opacity ${timing.toggle}ms ${ease};
}
/* The vertical stroke rotates away, leaving a minus. */
.kr-faq__toggle::after { transform: rotate(90deg); }
.kr-faq__item--open .kr-faq__toggle::before,
.kr-faq__item--open .kr-faq__toggle::after { background: ${color.toggleOpen}; }
.kr-faq__item--open .kr-faq__toggle::after { transform: rotate(0deg); opacity: 0; }

/* ── answer ───────────────────────────────────────────────
   grid-template-rows animates to the content's true height. */
.kr-faq__panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows ${timing.expand}ms ${ease};
}
.kr-faq__item--open .kr-faq__panel { grid-template-rows: 1fr; }
.kr-faq__panel-inner { overflow: hidden; }

@supports not (grid-template-rows: 0fr) {
  .kr-faq__panel {
    display: block;
    max-height: 0;
    overflow: hidden;
    transition: max-height ${timing.expand}ms ${ease};
  }
  .kr-faq__item--open .kr-faq__panel { max-height: 420px; }
}

.kr-faq__answer {
  margin: ${spacing.answerTop}px 0 ${spacing.answerBottom}px;
  /* Aligns the answer under the question, past the number column. */
  margin-left: calc(${typography.numberSize}px * 2.6 + ${spacing.numberGap}px);
  padding-left: ${spacing.answerIndent}px;
  border-left: ${layout.answerRuleWidth}px solid ${color.answerRule};
  color: ${color.answer};
  font-family: ${typography.answerFamily};
  font-size: ${typography.answerSize}px;
  font-weight: ${typography.answerWeight};
  line-height: ${typography.answerLeading};
  max-width: 60ch;
}

/* ── responsive ───────────────────────────────────────── */
@media (max-width: ${layout.stackBelow}px) {
  .kr-faq {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-faq__inner {
    grid-template-columns: minmax(0, 1fr);
    gap: ${spacing.columnGapCompact}px;
    padding: 0 ${spacing.gutterCompact}px;
  }
  /* Help prompt moves under the questions, where it is actually needed. */
  .kr-faq__help { order: 3; margin-top: 8px; }
  .kr-faq__list-wrap { order: 2; }
}

@media (max-width: 560px) {
  .kr-faq__trigger { gap: 14px; }
  .kr-faq__answer { margin-left: 0; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-faq__item,
  .kr-faq__panel,
  .kr-faq__toggle::before,
  .kr-faq__toggle::after,
  .kr-faq__question,
  .kr-faq__help-arrow {
    transition: none;
  }
  .kr-faq__item { opacity: 1; transform: none; }
}
`;

/** Without JavaScript the rows never reveal; answers stay reachable. */
const noscriptCss = `
.kr-faq__item { opacity: 1; transform: none; }
.kr-faq__panel { grid-template-rows: 1fr; }
.kr-faq__toggle { display: none; }
`;

const template: FaqTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-faq",
  timing,
  labels,
};

export default template;
