import React from "react";
import type { HeadFC, PageProps } from "gatsby";

import Layout from "../components/Layout";
import BenefitsX from "../ppm/primitives/benefits/benefits-x";
import FaqX from "../ppm/primitives/faq/faq-x";
import FinalCtaX from "../ppm/primitives/final-cta/final-cta-x";
import HeroX from "../ppm/primitives/hero/hero-x";
import HowItWorksX from "../ppm/primitives/how-it-works/how-it-works-x";
import FeaturedProperties from "../ppm/primitives/property/featured-properties";
import TrustStripX from "../ppm/primitives/trust-strip/trust-strip-x";
import WhyChooseX from "../ppm/primitives/why-choose/why-choose-x";

/**
 * The homepage.
 *
 * Every section is a configured primitive, so this file is the running order
 * and nothing else - no layout, no copy, no styling. The header and footer
 * come from Layout.
 */
export default function IndexPage(_props: PageProps) {
  return (
    <Layout heroLed>
      <HeroX />
      <TrustStripX />
      <FeaturedProperties />
      <BenefitsX />
      <HowItWorksX />
      <WhyChooseX />
      <FaqX />
      <FinalCtaX />
    </Layout>
  );
}

export const Head: HeadFC = () => (
  <>
    <title>Kelley Road Property Management</title>
    <meta
      name="description"
      content="Professionally managed apartments, homes and townhomes across Massachusetts. Browse available rentals and apply online."
    />
  </>
);
