import React, { useState } from "react";
import { Link } from "gatsby";
import { LuArrowRight } from "react-icons/lu";

import type { FaqTemplate } from "../../templates/faq/default-template";
import useInView from "../shared/useInView";
import type { FaqEntry } from "./types";

export type FaqProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: FaqTemplate;
  entries: FaqEntry[];
  /** Section heading. Passed in so this reuses the shared SectionTitle. */
  heading?: React.ReactNode;
  lede?: string;
  help?: { title: string; label: string; href: string };
  /** Index open on first render. Pass -1 for all closed. */
  initialOpen?: number;
  enabled?: boolean;
};

const pad = (n: number) => String(n).padStart(2, "0");

/**
 * The FAQ accordion.
 *
 * One panel open at a time: with seven short answers, allowing several open
 * turns the column into a wall of text and loses the scannable question list
 * that makes an FAQ useful.
 *
 * Each row is a real <button> with aria-expanded and aria-controls, so the
 * control is reachable and announced correctly without any extra ARIA
 * scaffolding.
 */
export default function Faq({
  template,
  entries,
  heading,
  lede,
  help,
  initialOpen = 0,
  enabled = true,
}: FaqProps) {
  const { ref, inView } = useInView<HTMLElement>({ threshold: 0.1 });
  const [openIndex, setOpenIndex] = useState(initialOpen);

  if (!enabled || entries.length === 0) return null;

  const root = template.rootClass;

  return (
    <section ref={ref} className={`${root}${inView ? ` ${root}--in` : ""}`}>
      <style>{template.css}</style>
      <noscript>
        <style>{template.noscriptCss}</style>
      </noscript>

      <div className={`${root}__inner`}>
        <div className={`${root}__intro`}>
          {heading}
          {lede ? <p className={`${root}__lede`}>{lede}</p> : null}

          {help ? (
            <div className={`${root}__help`}>
              <p className={`${root}__help-title`}>{help.title}</p>
              <Link className={`${root}__help-link`} to={help.href}>
                {help.label}
                <span className={`${root}__help-arrow`} aria-hidden="true">
                  <LuArrowRight size={13} strokeWidth={1.75} />
                </span>
              </Link>
            </div>
          ) : null}
        </div>

        <div className={`${root}__list-wrap`}>
          <ul className={`${root}__list`}>
            {entries.map((entry, index) => {
              const open = index === openIndex;
              const panelId = `${root}-panel-${entry.id}`;
              const buttonId = `${root}-button-${entry.id}`;

              return (
                <li
                  key={entry.id}
                  className={`${root}__item${open ? ` ${root}__item--open` : ""}`}
                  style={{
                    ["--kr-faq-delay" as string]: `${index * template.timing.rowStagger}ms`,
                  }}
                >
                  <button
                    type="button"
                    id={buttonId}
                    className={`${root}__trigger`}
                    aria-expanded={open}
                    aria-controls={panelId}
                    onClick={() => setOpenIndex(open ? -1 : index)}
                  >
                    <span className={`${root}__number`}>{pad(index + 1)}</span>
                    <span className={`${root}__question`}>{entry.question}</span>
                    <span className={`${root}__toggle`} aria-hidden="true" />
                  </button>

                  <div
                    id={panelId}
                    className={`${root}__panel`}
                    role="region"
                    aria-labelledby={buttonId}
                    /* Hidden from assistive tech while collapsed, so a closed
                       answer is not read out as page text. */
                    {...(open ? {} : { inert: "" })}
                  >
                    <div className={`${root}__panel-inner`}>
                      <p className={`${root}__answer`}>{entry.answer}</p>
                    </div>
                  </div>
                </li>
              );
            })}
          </ul>
        </div>
      </div>
    </section>
  );
}
