import React from "react";
import { Link } from "gatsby";
import { LuArrowRight } from "react-icons/lu";

import type { FinalCtaTemplate } from "../../templates/final-cta/default-template";
import useInView from "../shared/useInView";

export type FinalCtaContent = {
  eyebrow: string;
  title: string;
  description: string;
  image: { src: string; srcSet?: string; alt: string; position?: string };
  primary: { label: string; href: string };
  secondary?: { label: string; href: string };
};

export type FinalCtaProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: FinalCtaTemplate;
  content: FinalCtaContent;
  enabled?: boolean;
};

/**
 * The last message before the footer.
 *
 * Deliberately spare: one heading, one line, two actions. Anything more turns
 * a conversion moment into another content section.
 */
export default function FinalCta({
  template,
  content,
  enabled = true,
}: FinalCtaProps) {
  const { ref, inView } = useInView<HTMLElement>({ threshold: 0.2 });

  if (!enabled) return null;

  const root = template.rootClass;

  return (
    <section ref={ref} className={`${root}${inView ? ` ${root}--in` : ""}`}>
      <style>{template.css}</style>
      <noscript>
        <style>{template.noscriptCss}</style>
      </noscript>

      <div className={`${root}__media`}>
        <img
          className={`${root}__image`}
          src={content.image.src}
          srcSet={content.image.srcSet}
          sizes={content.image.srcSet ? "100vw" : undefined}
          alt={content.image.alt}
          style={
            content.image.position
              ? { objectPosition: content.image.position }
              : undefined
          }
          loading="lazy"
          decoding="async"
        />
      </div>
      <div className={`${root}__scrim`} aria-hidden="true" />

      <div className={`${root}__inner`}>
        <div className={`${root}__content`}>
          <span className={`${root}__rule`} aria-hidden="true" />
          <p className={`${root}__eyebrow`}>{content.eyebrow}</p>
          <h2 className={`${root}__title`}>{content.title}</h2>
          <p className={`${root}__description`}>{content.description}</p>

          <div className={`${root}__actions`}>
            <Link className="kr-btn kr-btn--gold" to={content.primary.href}>
              {content.primary.label}
              <LuArrowRight size={14} strokeWidth={1.75} aria-hidden="true" />
            </Link>
            {content.secondary ? (
              <Link
                className={`kr-btn kr-btn--outline ${root}__secondary`}
                to={content.secondary.href}
              >
                {content.secondary.label}
              </Link>
            ) : null}
          </div>
        </div>
      </div>
    </section>
  );
}
