import { useEffect, useState } from "react";

export type ParsedStat = {
  number: number;
  /** Anything trailing the digits, e.g. the "+" in "25+". */
  suffix: string;
};

/**
 * Splits a display value into a number and its suffix, or returns null when
 * the value is not a real figure.
 *
 * "25+"       -> { number: 25, suffix: "+" }
 * "XX"        -> null   (placeholder — must never animate to a made-up number)
 * "Dedicated" -> null
 */
export function parseStatValue(value: string): ParsedStat | null {
  const match = /^(\d+)(\D*)$/.exec(value.trim());
  if (!match) return null;
  return { number: Number(match[1]), suffix: match[2] };
}

/** True for the `XX`-style placeholders, which get a muted treatment. */
export function isPlaceholder(value: string): boolean {
  return /^x+$/i.test(value.trim());
}

const easeOutCubic = (t: number) => 1 - Math.pow(1 - t, 3);

type Options = {
  /** Final value, or null when this statistic is not numeric. */
  target: number | null;
  /** Start counting once the section has been revealed. */
  active: boolean;
  duration: number;
  delay: number;
};

/**
 * Counts from zero to `target` once `active` turns true.
 *
 * Returns null when there is nothing to count, so the caller renders the raw
 * string instead. Honours prefers-reduced-motion by jumping straight to the
 * final figure rather than animating.
 */
export function useCountUp({ target, active, duration, delay }: Options): number | null {
  const [display, setDisplay] = useState(0);

  useEffect(() => {
    if (target === null || !active) return;

    const reduced =
      typeof window !== "undefined" &&
      typeof window.matchMedia === "function" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    if (reduced) {
      setDisplay(target);
      return;
    }

    let frame = 0;
    let start = 0;
    let cancelled = false;

    const timer = setTimeout(() => {
      const step = (now: number) => {
        if (cancelled) return;
        if (!start) start = now;

        const progress = Math.min((now - start) / duration, 1);
        setDisplay(Math.round(easeOutCubic(progress) * target));

        if (progress < 1) frame = requestAnimationFrame(step);
      };

      frame = requestAnimationFrame(step);
    }, delay);

    return () => {
      cancelled = true;
      clearTimeout(timer);
      if (frame) cancelAnimationFrame(frame);
    };
  }, [target, active, duration, delay]);

  return target === null ? null : display;
}

export default useCountUp;
