import React from "react";

import type { TrustStripTemplate } from "../../templates/trust-strip/default-template";
import useInView from "../shared/useInView";
import type { TrustStat } from "./types";
import useCountUp, { isPlaceholder, parseStatValue } from "./useCountUp";

export type TrustStripProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: TrustStripTemplate;
  stats: TrustStat[];
  /**
   * The section heading. Passed in rather than built here so the strip reuses
   * the shared SectionTitle primitive instead of growing a second one.
   */
  heading?: React.ReactNode;
  /** Use the warm off-white section background instead of white. */
  alt?: boolean;
  enabled?: boolean;
};

/** One column. Split out so all four render through the same code path. */
function TrustItem({
  stat,
  index,
  template,
  active,
}: {
  stat: TrustStat;
  index: number;
  template: TrustStripTemplate;
  active: boolean;
}) {
  const root = template.rootClass;
  const Icon = stat.icon;

  const parsed = parseStatValue(stat.value);
  const placeholder = isPlaceholder(stat.value);

  const counted = useCountUp({
    target: parsed ? parsed.number : null,
    active,
    duration: template.timing.countUp,
    delay: template.timing.countUpDelay + index * template.timing.stagger,
  });

  const valueClasses = [
    `${root}__value`,
    parsed ? "" : `${root}__value--word`,
    placeholder ? `${root}__value--placeholder` : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div className={`${root}__item`}>
      <div
        className={`${root}__body`}
        style={{ ["--kr-trust-delay" as string]: `${index * template.timing.stagger}ms` }}
      >
        <span className={`${root}__ring`} aria-hidden="true">
          <Icon
            size={template.layout.iconSize}
            strokeWidth={template.layout.iconStroke}
          />
        </span>

        {/* The figure is announced from the source string, never from the
            mid-animation count. */}
        <p className={valueClasses} aria-label={stat.value}>
          {parsed ? (
            <>
              <span aria-hidden="true">{counted}</span>
              {parsed.suffix ? (
                <span className={`${root}__value-accent`} aria-hidden="true">
                  {parsed.suffix}
                </span>
              ) : null}
            </>
          ) : (
            stat.value
          )}
        </p>

        <p className={`${root}__label`}>{stat.label}</p>
      </div>
    </div>
  );
}

/**
 * The trust / statistics strip.
 *
 * Data-driven: every column renders through one component, so a fifth
 * statistic is a new record, never new markup.
 */
export default function TrustStrip({
  template,
  stats,
  heading,
  alt = false,
  enabled = true,
}: TrustStripProps) {
  const { ref, inView } = useInView<HTMLElement>();

  if (!enabled || stats.length === 0) return null;

  const root = template.rootClass;

  return (
    <section
      ref={ref}
      className={`${root}${alt ? ` ${root}--alt` : ""}${inView ? ` ${root}--in` : ""}`}
    >
      <style>{template.css}</style>
      {/* The reveal is observer-driven; without JS the columns would never
          be shown. */}
      <noscript>
        <style>{template.noscriptCss}</style>
      </noscript>

      <div className={`${root}__inner`}>
        {heading ? <div className={`${root}__heading`}>{heading}</div> : null}

        <div className={`${root}__grid`}>
          {stats.map((stat, index) => (
            <TrustItem
              key={stat.label}
              stat={stat}
              index={index}
              template={template}
              active={inView}
            />
          ))}
        </div>
      </div>
    </section>
  );
}
