import brand from "../../brand";

// Colour only.
//
// The scrim is the load-bearing decision here. The reference carousel drowns
// its photography in flat black; the brief explicitly rejects that. So instead
// of one global overlay we use two directional gradients that overlap only in
// the lower-left, where the text sits. The upper-right of every photograph is
// left essentially untouched.
const color = {
  /** Fallback behind the photograph while it loads. */
  stage: brand.colors.primary,

  /** Bottom-up wash. Strong at the very bottom, gone by mid-frame. */
  scrimVertical:
    "linear-gradient(to top, rgba(31,35,40,.80) 0%, rgba(31,35,40,.46) 28%, rgba(31,35,40,.12) 55%, rgba(31,35,40,0) 78%)",
  /** Left-to-right wash. Carries the text column, clears well before centre. */
  scrimHorizontal:
    "linear-gradient(to right, rgba(31,35,40,.58) 0%, rgba(31,35,40,.22) 34%, rgba(31,35,40,0) 62%)",

  eyebrow: brand.colors.accent,
  title: brand.colors.onPrimary,
  description: "rgba(255, 255, 255, 0.86)",

  ctaText: brand.colors.onPrimary,
  ctaHover: brand.colors.accent,
  ctaRule: "rgba(255, 255, 255, 0.42)",
  ctaRuleHover: brand.colors.accent,

  /* ── controls ── */
  controlText: "rgba(255, 255, 255, 0.55)",
  controlActive: brand.colors.accent,
  controlBorder: "rgba(255, 255, 255, 0.28)",
  controlHoverBorder: brand.colors.accent,
  /** Progress hairline under the active index. */
  controlRail: "rgba(255, 255, 255, 0.20)",

  /* ── search card ── */
  searchBackground: brand.colors.background,
  searchShadow: "0 18px 50px rgba(31, 35, 40, .18), 0 2px 6px rgba(31, 35, 40, .06)",
  searchBorder: brand.colors.border,
  searchDivider: brand.colors.border,
  searchLabel: "rgba(255, 255, 255, 0.78)",
  searchText: brand.colors.text,
  searchPlaceholder: brand.colors.textMuted,
  searchIcon: brand.colors.textMuted,
  searchFocusRing: brand.colors.accent,
  searchFilterHover: brand.colors.backgroundAlt,
};

export default color;
