import React from "react";

import cardTemplate from "../../config/property-card--template";
import carouselTemplate from "../../config/property-carousel--template";
import PropertyCarousel from "../../modules/property/PropertyCarousel";
import featuredEnabled from "../../toggles/featured-properties";
import SectionTitle from "../section-title/section-title";
import { publishedOnly } from "../../modules/property/derive";
import { catalogue as properties } from "./catalogue";
import { resolveProperties } from "./property-images";

/**
 * The homepage Featured Properties carousel, configured.
 *
 * Listings come from the shared property records, so the carousel and the
 * property pages can never drift apart. To build Similar Properties later,
 * render PropertyCarousel with a filtered slice of the same array.
 */
export default function FeaturedProperties() {
  return (
    <PropertyCarousel
      template={carouselTemplate}
      cardTemplate={cardTemplate}
      enabled={featuredEnabled}
      properties={resolveProperties(publishedOnly(properties))}
      heading={
        <SectionTitle
          backgroundText="Properties"
          title="Featured Properties"
          description="Explore our latest available homes and find a space that feels right for you."
          align="left"
        />
      }
    />
  );
}
