// Styling for the homepage hero carousel and its property search.
// Swap via config/hero--template.ts to restyle without touching a component.
//
// Three deliberate departures from the reference:
//
// 1. No flat black overlay. Two directional gradients cross in the lower-left
//    only, so the text is legible while the rest of the photograph keeps its
//    real colour. See template-1/color.ts.
// 2. The information lands fast — 300ms animations offset 100ms apart, rather
//    than the slow sequence the brief called out.
// 3. The zoom runs continuously on every slide rather than restarting on the
//    active one. Restarting means the outgoing slide snaps back to scale(1)
//    while it is still visible mid-crossfade; a continuous slow drift avoids
//    that entirely and reads as one cohesive camera move across the carousel.

import template1 from "./template-1";

export type HeroLabels = {
  /** Label above the search card. */
  searchLabel: string;
  searchTypeLabel: string;
  searchQueryLabel: string;
  searchPlaceholder: string;
  searchSubmit: string;
  filterLabel: string;
  previousSlide: string;
  nextSlide: string;
  /** `{n}` is replaced with the slide number. */
  goToSlide: string;
  carouselLabel: string;
};

export type HeroTemplate = {
  css: string;
  rootClass: string;
  timing: typeof template1.timing;
  labels: HeroLabels;
};

const { color, layout, spacing, timing, typography } = template1;

const labels: HeroLabels = {
  searchLabel: "Find a Property",
  searchTypeLabel: "Bedrooms",
  searchQueryLabel: "Location or property name",
  searchPlaceholder: "City, neighborhood or property name",
  searchSubmit: "Search",
  filterLabel: "More filters",
  previousSlide: "Previous slide",
  nextSlide: "Next slide",
  goToSlide: "Go to slide {n}",
  carouselLabel: "Featured properties",
};

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-hero {
  position: relative;
  min-height: ${layout.minHeightFallback};
  min-height: ${layout.minHeight};
  display: flex;
  background: ${color.stage};
  overflow: hidden;
  isolation: isolate;
}

/* ── photography ──────────────────────────────────────── */
.kr-hero__stage {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.kr-hero__slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity ${timing.fade}ms ${ease};
  will-change: opacity;
}
.kr-hero__slide--active { opacity: 1; }

.kr-hero__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
  /* Continuous, never restarted — see the note at the top of this file. */
  animation: kr-hero-drift ${timing.zoom}ms ease-in-out infinite alternate;
}
@keyframes kr-hero-drift {
  from { transform: scale(1); }
  to   { transform: scale(${layout.zoomTo}); }
}

/* Two crossing gradients rather than one flat wash. */
.kr-hero__scrim {
  position: absolute;
  inset: 0;
  z-index: 1;
  background-image: ${color.scrimVertical}, ${color.scrimHorizontal};
  pointer-events: none;
}

/* ── layout ───────────────────────────────────────────── */
.kr-hero__inner {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: ${spacing.contentTop}px ${spacing.gutter}px ${spacing.contentBottom}px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: ${spacing.ctaGap}px;
}

/* ── slide content ────────────────────────────────────── */
.kr-hero__content { max-width: ${layout.contentMaxWidth}px; }

.kr-hero__eyebrow {
  margin: 0 0 ${spacing.eyebrowGap}px;
  color: ${color.eyebrow};
  font-family: ${typography.eyebrowFamily};
  font-size: ${typography.eyebrowSize}px;
  font-weight: ${typography.eyebrowWeight};
  letter-spacing: ${typography.eyebrowTracking};
  text-transform: uppercase;
}

.kr-hero__title {
  margin: 0 0 ${spacing.titleGap}px;
  max-width: ${layout.titleMaxWidth};
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
  line-height: ${typography.titleLeading};
}

.kr-hero__description {
  margin: 0 0 ${spacing.descriptionGap}px;
  max-width: ${layout.descriptionMaxWidth};
  color: ${color.description};
  font-family: ${typography.descriptionFamily};
  font-size: ${typography.descriptionSize};
  font-weight: ${typography.descriptionWeight};
  line-height: ${typography.descriptionLeading};
}

.kr-hero__cta {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 7px;
  border-bottom: 1px solid ${color.ctaRule};
  color: ${color.ctaText};
  font-family: ${typography.ctaFamily};
  font-size: ${typography.ctaSize}px;
  font-weight: ${typography.ctaWeight};
  letter-spacing: ${typography.ctaTracking};
  text-transform: uppercase;
  text-decoration: none;
  transition: color .24s ${ease}, border-color .24s ${ease};
}
.kr-hero__cta:hover {
  color: ${color.ctaHover};
  border-bottom-color: ${color.ctaRuleHover};
}
.kr-hero__cta:focus-visible {
  outline: 2px solid ${color.ctaHover};
  outline-offset: 5px;
}
.kr-hero__cta-arrow { transition: transform .24s ${ease}; }
.kr-hero__cta:hover .kr-hero__cta-arrow { transform: translateX(5px); }

/* ── entrance stagger ─────────────────────────────────────
   The content wrapper is keyed on the slide index, so React remounts it on
   every change and these animations re-run from the start. */
@keyframes kr-hero-enter {
  from { opacity: 0; transform: translate3d(-10px, 16px, 0); }
  to   { opacity: 1; transform: none; }
}
.kr-hero__eyebrow,
.kr-hero__title,
.kr-hero__description,
.kr-hero__cta {
  animation: kr-hero-enter ${timing.contentDuration}ms ${ease} both;
}
.kr-hero__eyebrow     { animation-delay: ${timing.eyebrowDelay}ms; }
.kr-hero__title       { animation-delay: ${timing.titleDelay}ms; }
.kr-hero__description { animation-delay: ${timing.descriptionDelay}ms; }
.kr-hero__cta         { animation-delay: ${timing.ctaDelay}ms; }

/* ── bottom row: search + controls ────────────────────── */
.kr-hero__bottom {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
}

.kr-hero__search-block {
  flex: 1 1 auto;
  min-width: 0;
  max-width: ${layout.searchMaxWidth}px;
}

.kr-hero__search-label {
  margin: 0 0 ${spacing.searchLabelGap}px;
  color: ${color.searchLabel};
  font-family: ${typography.searchLabelFamily};
  font-size: ${typography.searchLabelSize}px;
  font-weight: ${typography.searchLabelWeight};
  letter-spacing: ${typography.searchLabelTracking};
  text-transform: uppercase;
}

/* ── search card ──────────────────────────────────────── */
.kr-search {
  display: flex;
  align-items: center;
  padding: ${spacing.searchPaddingX}px;
  background: ${color.searchBackground};
  border: 1px solid ${color.searchBorder};
  border-radius: ${layout.searchRadius}px;
  box-shadow: ${color.searchShadow};
}

.kr-search__field {
  display: flex;
  align-items: center;
  gap: 11px;
  flex: 1 1 auto;
  min-width: 0;
  height: ${layout.searchHeight - spacing.searchPaddingX * 2}px;
  padding: 0 ${spacing.searchFieldPaddingX}px;
}
.kr-search__field--type {
  flex: 0 0 ${layout.selectWidth}px;
  position: relative;
}

.kr-search__icon {
  display: inline-flex;
  color: ${color.searchIcon};
  flex-shrink: 0;
}

.kr-search__select,
.kr-search__input {
  width: 100%;
  min-width: 0;
  border: 0;
  background: none;
  outline: none;
  color: ${color.searchText};
  font-family: ${typography.searchFieldFamily};
  font-size: ${typography.searchFieldSize}px;
  font-weight: ${typography.searchFieldWeight};
}
.kr-search__input::placeholder {
  color: ${color.searchPlaceholder};
  font-weight: 400;
}
.kr-search__select {
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
  padding-right: 18px;
}
.kr-search__caret {
  position: absolute;
  right: ${spacing.searchFieldPaddingX}px;
  display: inline-flex;
  color: ${color.searchIcon};
  pointer-events: none;
}

/* Focus lands on the field wrapper, not the bare input, so the whole cell
   reads as active. */
.kr-search__field:focus-within {
  box-shadow: inset 0 0 0 1px ${color.searchFocusRing};
  border-radius: ${layout.searchRadius}px;
}

.kr-search__divider {
  width: 1px;
  height: 26px;
  background: ${color.searchDivider};
  flex-shrink: 0;
}

.kr-search__filter {
  width: ${layout.filterSize}px;
  height: ${layout.filterSize}px;
  flex-shrink: 0;
  margin-right: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid ${color.searchBorder};
  border-radius: ${layout.searchRadius}px;
  background: none;
  color: ${color.searchIcon};
  cursor: pointer;
  transition: background-color .2s ${ease}, color .2s ${ease}, border-color .2s ${ease};
}
.kr-search__filter:hover {
  background: ${color.searchFilterHover};
  color: ${color.searchText};
  border-color: ${color.searchFocusRing};
}
.kr-search__filter:focus-visible {
  outline: 2px solid ${color.searchFocusRing};
  outline-offset: 2px;
}

.kr-search__submit {
  flex-shrink: 0;
  height: ${layout.searchHeight - spacing.searchPaddingX * 2}px;
}

/* ── controls ─────────────────────────────────────────── */
.kr-hero__controls {
  display: flex;
  align-items: center;
  gap: ${spacing.controlGap}px;
  flex-shrink: 0;
  padding-bottom: 4px;
}

.kr-hero__arrow {
  width: ${layout.arrowSize}px;
  height: ${layout.arrowSize}px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid ${color.controlBorder};
  border-radius: 50%;
  background: none;
  color: ${color.title};
  cursor: pointer;
  transition: border-color .22s ${ease}, color .22s ${ease}, background-color .22s ${ease};
}
.kr-hero__arrow:hover {
  border-color: ${color.controlHoverBorder};
  color: ${color.controlActive};
}
.kr-hero__arrow:focus-visible {
  outline: 2px solid ${color.controlActive};
  outline-offset: 3px;
}

.kr-hero__indicators {
  display: flex;
  align-items: center;
  gap: ${spacing.indicatorGap}px;
  margin: 0 8px;
}

.kr-hero__indicator {
  position: relative;
  padding: 0 0 9px;
  border: 0;
  background: none;
  color: ${color.controlText};
  font-family: ${typography.indicatorFamily};
  font-size: ${typography.indicatorSize}px;
  font-weight: ${typography.indicatorWeight};
  letter-spacing: ${typography.indicatorTracking};
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition: color .22s ${ease};
}
/* Rail under every index; the active one fills gold. */
.kr-hero__indicator::before,
.kr-hero__indicator::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  height: 1px;
  width: ${layout.indicatorRailWidth}px;
}
.kr-hero__indicator::before { background: ${color.controlRail}; }
.kr-hero__indicator::after {
  background: ${color.controlActive};
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform .3s ${ease};
}
.kr-hero__indicator:hover { color: ${color.title}; }
.kr-hero__indicator--active { color: ${color.controlActive}; }
.kr-hero__indicator--active::after { transform: scaleX(1); }
.kr-hero__indicator:focus-visible {
  outline: 2px solid ${color.controlActive};
  outline-offset: 3px;
}

/* ── responsive ───────────────────────────────────────── */
@media (max-width: ${layout.navCollapseBelow}px) {
  .kr-hero {
    min-height: ${layout.minHeightCompact};
  }
  .kr-hero__inner {
    padding: ${spacing.contentTop - 40}px ${spacing.gutterCompact}px ${spacing.contentBottomCompact}px;
    gap: ${spacing.ctaGapCompact}px;
  }
  .kr-hero__title { max-width: 18ch; }
}

@media (max-width: ${layout.stackSearchBelow}px) {
  .kr-hero__bottom {
    flex-direction: column-reverse;
    align-items: stretch;
    gap: 22px;
  }
  .kr-hero__controls { justify-content: flex-start; padding-bottom: 0; }

  /* Stack, do not squeeze: type, then location, then a full-width action. */
  .kr-search {
    flex-direction: column;
    align-items: stretch;
    gap: ${spacing.searchStackGap}px;
    padding: ${spacing.searchStackGap}px;
  }
  .kr-search__field {
    flex: 1 1 auto;
    width: 100%;
    height: ${layout.searchHeightCompact - spacing.searchPaddingX * 2}px;
    border: 1px solid ${color.searchBorder};
    border-radius: ${layout.searchRadius}px;
  }
  .kr-search__field--type { flex: 1 1 auto; }
  .kr-search__divider,
  .kr-search__filter { display: none; }
  .kr-search__submit {
    width: 100%;
    height: ${layout.searchHeightCompact - spacing.searchPaddingX * 2}px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .kr-hero__image { animation: none; }
  .kr-hero__slide { transition-duration: .01ms; }
  .kr-hero__eyebrow,
  .kr-hero__title,
  .kr-hero__description,
  .kr-hero__cta {
    animation: none;
  }
  .kr-hero__indicator::after,
  .kr-hero__cta-arrow { transition-duration: .01ms; }
}
`;

const template: HeroTemplate = {
  css,
  rootClass: "kr-hero",
  timing,
  labels,
};

export default template;
