// Styling for the Why Choose Us editorial split.
//
// Three notes:
//
// 1. The image is not faded overall. A gradient sits only over its left edge,
//    where it meets the text column, so the photograph keeps full contrast and
//    colour everywhere else. The gradient is the section background colour, so
//    the edge dissolves rather than greying out.
//
// 2. The main photograph reveals with a clip-path wipe rather than a fade,
//    which is the section's signature motion. clip-path animates on the
//    compositor, so it stays smooth on modest hardware.
//
// 3. The inset sits in a white frame with its own shadow, overlapping the
//    main image's bottom-left. It is a separate positioned element rather than
//    a nested child, so it can escape the main image's overflow clipping.

import template1 from "./template-1";

export type WhyChooseTemplate = {
  css: string;
  noscriptCss: string;
  rootClass: string;
  timing: typeof template1.timing;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-why {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
  overflow: hidden;
}
.kr-why__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
  display: grid;
  grid-template-columns: ${layout.contentColumn} ${layout.visualColumn};
  align-items: center;
  gap: ${spacing.columnGap}px;
}

/* ── content column ───────────────────────────────────── */
.kr-why__lede {
  margin: ${spacing.ledeGap}px 0 0;
  color: ${color.lede};
  font-family: ${typography.ledeFamily};
  font-size: ${typography.ledeSize};
  font-weight: ${typography.ledeWeight};
  line-height: ${typography.ledeLeading};
  opacity: 0;
  transform: translateY(14px);
  transition:
    opacity ${timing.lede}ms ${ease} ${timing.ledeDelay}ms,
    transform ${timing.lede}ms ${ease} ${timing.ledeDelay}ms;
}
.kr-why--in .kr-why__lede { opacity: 1; transform: none; }

/* Editorial list, not three cards: numbers, rules, nothing boxed. */
.kr-why__points {
  margin: ${spacing.pointsGap}px 0 0;
  padding: 0;
  list-style: none;
}
.kr-why__point {
  display: flex;
  gap: ${spacing.pointNumberGap}px;
  padding: ${spacing.pointPaddingY}px 0;
  border-top: 1px solid ${color.pointDivider};
  opacity: 0;
  transform: translateY(14px);
  transition:
    opacity ${timing.point}ms ${ease} var(--kr-why-delay, 0ms),
    transform ${timing.point}ms ${ease} var(--kr-why-delay, 0ms);
}
.kr-why__point:last-child { border-bottom: 1px solid ${color.pointDivider}; }
.kr-why--in .kr-why__point { opacity: 1; transform: none; }

.kr-why__point-number {
  flex-shrink: 0;
  color: ${color.pointNumber};
  font-family: ${typography.pointNumberFamily};
  font-size: ${typography.pointNumberSize}px;
  font-weight: ${typography.pointNumberWeight};
  letter-spacing: ${typography.pointNumberTracking};
  line-height: 1.9;
}
.kr-why__point-title {
  margin: 0 0 ${spacing.pointTitleGap}px;
  color: ${color.pointTitle};
  font-family: ${typography.pointTitleFamily};
  font-size: ${typography.pointTitleSize};
  font-weight: ${typography.pointTitleWeight};
  letter-spacing: ${typography.pointTitleTracking};
}
.kr-why__point-text {
  margin: 0;
  color: ${color.pointText};
  font-family: ${typography.pointTextFamily};
  font-size: ${typography.pointTextSize}px;
  font-weight: ${typography.pointTextWeight};
  line-height: ${typography.pointTextLeading};
}

.kr-why__actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: ${spacing.ctaRowGap}px;
  margin-top: ${spacing.ctaGap}px;
  opacity: 0;
  transform: translateY(12px);
  transition:
    opacity ${timing.cta}ms ${ease} ${timing.ctaDelay}ms,
    transform ${timing.cta}ms ${ease} ${timing.ctaDelay}ms;
}
.kr-why--in .kr-why__actions { opacity: 1; transform: none; }

.kr-why__secondary {
  color: ${color.secondaryLink};
  font-family: ${typography.secondaryFamily};
  font-size: ${typography.secondarySize}px;
  font-weight: ${typography.secondaryWeight};
  letter-spacing: ${typography.secondaryTracking};
  text-transform: uppercase;
  text-decoration: none;
  transition: color .24s ${ease};
}
.kr-why__secondary:hover { color: ${color.secondaryLinkHover}; }
.kr-why__secondary:focus-visible { outline: 2px solid ${color.focus}; outline-offset: 3px; }

/* ── visual column ────────────────────────────────────────
   The bottom padding is the overhang budget: the inset and the charcoal block
   sit at bottom: 0 of this padded box, so they hang exactly this far below the
   photograph and can never be clipped by the section. */
.kr-why__visual {
  position: relative;
  isolation: isolate;
  padding-bottom: ${layout.visualPadBottom}px;
}

/* Charcoal block behind one corner, giving the photography something to
   sit against without turning the section dark. */
.kr-why__block {
  position: absolute;
  right: -${layout.blockOffsetX}px;
  bottom: 0;
  z-index: 0;
  width: ${layout.blockWidth};
  height: ${layout.blockHeight};
  background: ${color.block};
  pointer-events: none;
}
.kr-why__block::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(90deg, ${color.blockLines} 0 1px, transparent 1px 46px),
    repeating-linear-gradient(0deg, ${color.blockLines} 0 1px, transparent 1px 46px);
}

.kr-why__main {
  position: relative;
  z-index: 1;
  aspect-ratio: ${layout.mainAspect};
  border-radius: ${layout.radius}px;
  background: ${color.mediaPlaceholder};
  overflow: hidden;
  /* Signature motion: a right-to-left wipe rather than a fade. */
  clip-path: inset(0 100% 0 0);
  transition: clip-path ${timing.mainReveal}ms ${ease} ${timing.mainRevealDelay}ms;
}
.kr-why--in .kr-why__main { clip-path: inset(0 0 0 0); }

.kr-why__main-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform ${timing.hover}ms ${ease};
}
.kr-why__visual:hover .kr-why__main-image { transform: scale(${layout.mainZoom}); }

/* Left edge only — the rest of the photograph keeps its contrast. */
.kr-why__fade {
  position: absolute;
  inset: 0;
  z-index: 1;
  background-image: ${color.fade};
  pointer-events: none;
}

/* Thin gold line alongside the image. */
.kr-why__rule {
  position: absolute;
  left: -14px;
  top: 12%;
  z-index: 2;
  width: ${layout.ruleWidth}px;
  height: ${layout.ruleHeight};
  background: ${color.rule};
  transform: scaleY(0);
  transform-origin: top center;
  transition: transform ${timing.mainReveal}ms ${ease} ${timing.mainRevealDelay}ms;
}
.kr-why--in .kr-why__rule { transform: scaleY(1); }

/* ── inset photograph ─────────────────────────────────── */
.kr-why__inset {
  position: absolute;
  left: ${layout.insetOffsetX};
  bottom: 0;
  z-index: 2;
  width: ${layout.insetWidth};
  padding: ${layout.insetFrameWidth}px;
  background: ${color.insetFrame};
  border-radius: ${layout.radius}px;
  box-shadow: ${color.insetShadow};
  opacity: 0;
  transform: translateY(18px);
  transition:
    opacity ${timing.inset}ms ${ease} ${timing.insetDelay}ms,
    transform ${timing.inset}ms ${ease} ${timing.insetDelay}ms;
}
.kr-why--in .kr-why__inset { opacity: 1; transform: translateY(0); }
.kr-why--in .kr-why__visual:hover .kr-why__inset {
  transform: translateY(${layout.insetLift}px);
  transition-delay: 0ms;
  transition-duration: ${timing.hover}ms;
}
.kr-why__inset-figure {
  display: block;
  aspect-ratio: ${layout.insetAspect};
  border-radius: 1px;
  overflow: hidden;
  background: ${color.mediaPlaceholder};
}
.kr-why__inset-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* ── experience badge ─────────────────────────────────── */
.kr-why__badge {
  position: absolute;
  right: -18px;
  top: 8%;
  z-index: 3;
  width: ${layout.badgeSize}px;
  height: ${layout.badgeSize}px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 12px;
  text-align: center;
  background: ${color.badgeBackground};
  border-radius: 50%;
  box-shadow: ${color.badgeShadow};
  opacity: 0;
  transform: scale(.9);
  transition:
    opacity ${timing.badge}ms ${ease} ${timing.badgeDelay}ms,
    transform ${timing.badge}ms ${ease} ${timing.badgeDelay}ms;
}
.kr-why--in .kr-why__badge { opacity: 1; transform: scale(1); }

.kr-why__badge-value {
  color: ${color.badgeValue};
  font-family: ${typography.badgeValueFamily};
  font-size: ${typography.badgeValueSize}px;
  font-weight: ${typography.badgeValueWeight};
  letter-spacing: -0.03em;
  line-height: 1;
}
.kr-why__badge-accent { color: ${color.badgeAccent}; }
.kr-why__badge-label {
  color: ${color.badgeLabel};
  font-family: ${typography.badgeLabelFamily};
  font-size: ${typography.badgeLabelSize}px;
  font-weight: ${typography.badgeLabelWeight};
  letter-spacing: ${typography.badgeLabelTracking};
  text-transform: uppercase;
  line-height: 1.4;
}

/* ── responsive ───────────────────────────────────────────
   Recomposed rather than squeezed: the visual moves above the trust points so
   the reading order becomes heading, image pair, badge, points, CTA. */
@media (max-width: ${layout.stackBelow}px) {
  .kr-why {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-why__inner {
    grid-template-columns: minmax(0, 1fr);
    gap: ${spacing.columnGapCompact}px;
    padding: 0 ${spacing.gutterCompact}px;
  }
  .kr-why__visual { order: -1; max-width: 520px; }
  .kr-why__main { aspect-ratio: 4 / 3; }
  .kr-why__inset { width: 44%; left: auto; right: 4%; bottom: 0; }
  .kr-why__badge {
    right: auto;
    left: 2%;
    top: auto;
    bottom: 6px;
    width: 108px;
    height: 108px;
  }
  .kr-why__rule { display: none; }
  .kr-why__block { right: -16px; }
  .kr-why__points { margin-top: 24px; }
}

@media (max-width: 520px) {
  .kr-why__inset { width: 48%; right: 0; }
  .kr-why__badge { width: 88px; height: 88px; left: 0; }
  .kr-why__points { margin-top: 24px; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-why__lede,
  .kr-why__point,
  .kr-why__actions,
  .kr-why__inset,
  .kr-why__badge {
    opacity: 1;
    transform: none;
    transition: none;
  }
  .kr-why__main { clip-path: inset(0 0 0 0); transition: none; }
  .kr-why__rule { transform: scaleY(1); transition: none; }
  .kr-why__main-image { transition: none; }
  .kr-why--in .kr-why__visual:hover .kr-why__inset { transform: none; }
  .kr-why__visual:hover .kr-why__main-image { transform: none; }
}
`;

/** Without JavaScript the reveal class never lands. */
const noscriptCss = `
.kr-why__lede,
.kr-why__point,
.kr-why__actions,
.kr-why__inset,
.kr-why__badge { opacity: 1; transform: none; }
.kr-why__main { clip-path: inset(0 0 0 0); }
.kr-why__rule { transform: scaleY(1); }
`;

const template: WhyChooseTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-why",
  timing,
};

export default template;
