import React from "react";
import { Link } from "gatsby";
import { FiArrowLeft, FiArrowRight } from "react-icons/fi";

import type { HeroLabels, HeroTemplate } from "../../templates/hero/default-template";
import PropertySearch from "./PropertySearch";
import type { HeroSlide, PropertyTypeOption } from "./types";
import useCarousel from "./useCarousel";

export type HeroCarouselProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: HeroTemplate;
  /** Slide records. One layout renders all of them — never one per slide. */
  slides: HeroSlide[];
  /** Property-type choices for the search select. */
  propertyTypes: PropertyTypeOption[];
  /** Where the search form resolves. */
  searchAction: string;
  enabled?: boolean;
  autoplay?: boolean;
  showSearch?: boolean;
  labels?: Partial<HeroLabels>;
};

const pad = (n: number) => String(n).padStart(2, "0");

/**
 * The hero mechanism: slide lifecycle, markup and the search slot. Holds no
 * colours, sizes or copy — those arrive via `template` and props, so the same
 * component renders whatever slide records the CMS eventually supplies.
 */
export default function HeroCarousel({
  template,
  slides,
  propertyTypes,
  searchAction,
  enabled = true,
  autoplay = true,
  showSearch = true,
  labels: labelOverrides,
}: HeroCarouselProps) {
  const labels = { ...template.labels, ...labelOverrides };

  const { index, goTo, next, previous, setInteracting } = useCarousel({
    count: slides.length,
    interval: template.timing.autoplay,
    autoplay,
  });

  if (!enabled || slides.length === 0) return null;

  const root = template.rootClass;
  const active = slides[Math.min(index, slides.length - 1)];
  const multiple = slides.length > 1;

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (!multiple) return;
    if (event.key === "ArrowRight") {
      event.preventDefault();
      next();
    } else if (event.key === "ArrowLeft") {
      event.preventDefault();
      previous();
    }
  };

  return (
    <section
      className={root}
      aria-roledescription="carousel"
      aria-label={labels.carouselLabel}
      onMouseEnter={() => setInteracting(true)}
      onMouseLeave={() => setInteracting(false)}
      onFocusCapture={() => setInteracting(true)}
      onBlurCapture={() => setInteracting(false)}
      onKeyDown={onKeyDown}
    >
      <style>{template.css}</style>

      <div className={`${root}__stage`}>
        {slides.map((slide, i) => (
          <div
            key={slide.image}
            className={`${root}__slide${i === index ? ` ${root}__slide--active` : ""}`}
            role="group"
            aria-roledescription="slide"
            aria-label={`${i + 1} of ${slides.length}`}
            aria-hidden={i !== index}
          >
            <img
              className={`${root}__image`}
              src={slide.image}
              srcSet={slide.imageSrcSet}
              sizes={slide.imageSrcSet ? "100vw" : undefined}
              alt={slide.imageAlt}
              /* The first frame is the largest paint on the page; the rest can
                 wait until the carousel actually needs them. */
              loading={i === 0 ? "eager" : "lazy"}
              decoding={i === 0 ? "sync" : "async"}
            />
          </div>
        ))}
      </div>

      <div className={`${root}__scrim`} aria-hidden="true" />

      <div className={`${root}__inner`}>
        {/* Keyed on the index so React remounts the block and the staggered
            entrance animations replay on every slide change. */}
        <div className={`${root}__content`} key={index}>
          {active.eyebrow ? (
            <p className={`${root}__eyebrow`}>{active.eyebrow}</p>
          ) : null}

          <h1 className={`${root}__title`}>{active.title}</h1>
          <p className={`${root}__description`}>{active.description}</p>

          <Link to={active.ctaLink} className={`${root}__cta`}>
            {active.ctaLabel}
            <span className={`${root}__cta-arrow`} aria-hidden="true">
              <FiArrowRight size={15} />
            </span>
          </Link>
        </div>

        <div className={`${root}__bottom`}>
          {showSearch ? (
            <div className={`${root}__search-block`}>
              <p className={`${root}__search-label`}>{labels.searchLabel}</p>
              <PropertySearch
                labels={labels}
                types={propertyTypes}
                action={searchAction}
              />
            </div>
          ) : (
            <div />
          )}

          {multiple ? (
            <div className={`${root}__controls`}>
              <button
                type="button"
                className={`${root}__arrow`}
                aria-label={labels.previousSlide}
                onClick={previous}
              >
                <FiArrowLeft size={16} />
              </button>

              <div className={`${root}__indicators`}>
                {slides.map((slide, i) => (
                  <button
                    key={slide.image}
                    type="button"
                    className={`${root}__indicator${
                      i === index ? ` ${root}__indicator--active` : ""
                    }`}
                    aria-label={labels.goToSlide.replace("{n}", String(i + 1))}
                    aria-current={i === index}
                    onClick={() => goTo(i)}
                  >
                    {pad(i + 1)}
                  </button>
                ))}
              </div>

              <button
                type="button"
                className={`${root}__arrow`}
                aria-label={labels.nextSlide}
                onClick={next}
              >
                <FiArrowRight size={16} />
              </button>
            </div>
          ) : null}
        </div>
      </div>
    </section>
  );
}
