import React from "react";
import { Link } from "gatsby";
import { LuArrowRight } from "react-icons/lu";

import type { WhyChooseTemplate } from "../../templates/why-choose/default-template";
import useInView from "../shared/useInView";
import type { WhyChooseContent } from "./types";

export type WhyChooseProps = {
  /** Structure, style and colour. Supplied by the primitive. */
  template: WhyChooseTemplate;
  content: WhyChooseContent;
  /** Section heading. Passed in so this reuses the shared SectionTitle. */
  heading?: React.ReactNode;
  enabled?: boolean;
};

/**
 * The Why Choose Us editorial split.
 *
 * Content on the left, a two-photograph composition on the right with the
 * experience badge between them. Everything here comes from `content`, so the
 * same component serves a different story with different copy and imagery.
 */
export default function WhyChoose({
  template,
  content,
  heading,
  enabled = true,
}: WhyChooseProps) {
  const { ref, inView } = useInView<HTMLElement>({ threshold: 0.12 });

  if (!enabled) return null;

  const root = template.rootClass;

  return (
    <section ref={ref} className={`${root}${inView ? ` ${root}--in` : ""}`}>
      <style>{template.css}</style>
      <noscript>
        <style>{template.noscriptCss}</style>
      </noscript>

      <div className={`${root}__inner`}>
        <div className={`${root}__content`}>
          {heading}

          <p className={`${root}__lede`}>{content.lede}</p>

          <ol className={`${root}__points`}>
            {content.points.map((point, index) => (
              <li
                key={point.number}
                className={`${root}__point`}
                style={{
                  ["--kr-why-delay" as string]: `${
                    template.timing.pointDelay + index * template.timing.pointStagger
                  }ms`,
                }}
              >
                <span className={`${root}__point-number`}>{point.number}</span>
                <div>
                  <h3 className={`${root}__point-title`}>{point.title}</h3>
                  <p className={`${root}__point-text`}>{point.description}</p>
                </div>
              </li>
            ))}
          </ol>

          <div className={`${root}__actions`}>
            <Link className="kr-btn kr-btn--gold" to={content.cta.href}>
              {content.cta.label}
              <LuArrowRight size={14} strokeWidth={1.75} aria-hidden="true" />
            </Link>
            {content.secondary ? (
              <Link className={`${root}__secondary`} to={content.secondary.href}>
                {content.secondary.label}
              </Link>
            ) : null}
          </div>
        </div>

        <div className={`${root}__visual`}>
          {/* Decorative geometry — never announced. */}
          <div className={`${root}__block`} aria-hidden="true" />
          <span className={`${root}__rule`} aria-hidden="true" />

          <div className={`${root}__main`}>
            <img
              className={`${root}__main-image`}
              src={content.mainImage.src}
              srcSet={content.mainImage.srcSet}
              sizes={content.mainImage.srcSet ? "(max-width: 980px) 90vw, 46vw" : undefined}
              alt={content.mainImage.alt}
              style={
                content.mainImage.position
                  ? { objectPosition: content.mainImage.position }
                  : undefined
              }
              loading="lazy"
              decoding="async"
            />
            <span className={`${root}__fade`} aria-hidden="true" />
          </div>

          <div className={`${root}__inset`}>
            <span className={`${root}__inset-figure`}>
              <img
                className={`${root}__inset-image`}
                src={content.insetImage.src}
                srcSet={content.insetImage.srcSet}
                sizes={content.insetImage.srcSet ? "(max-width: 980px) 44vw, 24vw" : undefined}
                alt={content.insetImage.alt}
                style={
                  content.insetImage.position
                    ? { objectPosition: content.insetImage.position }
                    : undefined
                }
                loading="lazy"
                decoding="async"
              />
            </span>
          </div>

          <div className={`${root}__badge`}>
            <span className={`${root}__badge-value`}>
              {content.experience.value}
              {content.experience.accent ? (
                <span className={`${root}__badge-accent`}>
                  {content.experience.accent}
                </span>
              ) : null}
            </span>
            <span className={`${root}__badge-label`}>{content.experience.label}</span>
          </div>
        </div>
      </div>
    </section>
  );
}
