// Styling for the trust / statistics strip beneath the hero.
// Swap via config/trust-strip--template.ts to restyle without touching a
// component.
//
// Three structural notes:
//
// 1. No cards. The brief does not want four generic SaaS feature boxes, so the
//    columns carry no background or shadow. Structure comes from a hairline
//    ring around each icon and a single hairline between columns.
//
// 2. Each column is item > body. The separators are pseudo-elements of the
//    item and the hover lift is a transform on the body — keeping them on
//    different elements stops the separator sliding up with the content.
//
// 3. 2x2 all the way down. No single-column breakpoint: four short statistics
//    stacked vertically turn a compact trust cue into a long scroll.

import template1 from "./template-1";

export type TrustStripTemplate = {
  css: string;
  noscriptCss: string;
  rootClass: string;
  timing: typeof template1.timing;
  /** Exposed so the component can size icons from tokens, not literals. */
  layout: typeof template1.layout;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const css = `
.kr-trust {
  background: ${color.background};
  padding: ${spacing.sectionTop}px 0 ${spacing.sectionBottom}px;
}
.kr-trust--alt { background: ${color.backgroundAlt}; }

.kr-trust__inner {
  max-width: ${layout.maxWidth}px;
  margin: 0 auto;
  padding: 0 ${spacing.gutter}px;
}

.kr-trust__heading { margin-bottom: ${spacing.headingGap}px; }

/* ── grid ─────────────────────────────────────────────────
   Framed top and bottom by a hairline. Reads as an architectural rule across
   the page rather than as a container around a box. */
.kr-trust__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  padding: ${spacing.gridPaddingY}px 0;
  border-top: 1px solid ${color.frame};
  border-bottom: 1px solid ${color.frame};
}

.kr-trust__item {
  position: relative;
  padding: 0 ${spacing.columnPaddingX}px;
  text-align: center;
}

/* Hairline between columns, plus a short gold segment over it. */
.kr-trust__item + .kr-trust__item::before,
.kr-trust__item + .kr-trust__item::after {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
}
.kr-trust__item + .kr-trust__item::before {
  width: ${layout.separatorWidth}px;
  height: ${layout.separatorHeight};
  background: ${color.separator};
}
.kr-trust__item + .kr-trust__item::after {
  width: ${layout.separatorWidth}px;
  height: ${layout.separatorAccentHeight}px;
  background: ${color.separatorAccent};
}

/* ── column body ──────────────────────────────────────── */
.kr-trust__body {
  display: flex;
  flex-direction: column;
  align-items: center;
  opacity: 0;
  transform: translateY(18px);
  transition:
    opacity ${timing.item}ms ${ease} var(--kr-trust-delay, 0ms),
    transform ${timing.item}ms ${ease} var(--kr-trust-delay, 0ms);
}
.kr-trust--in .kr-trust__body {
  opacity: 1;
  transform: translateY(0);
}

/* Hover lift. Small, and only once the column has finished arriving. */
.kr-trust--in .kr-trust__item:hover .kr-trust__body {
  transform: translateY(${layout.hoverLift}px);
  transition-delay: 0ms;
  transition-duration: ${timing.hover}ms;
}

/* ── icon ring ────────────────────────────────────────────
   A hairline circle, not a card: it anchors the column and gives the gold
   somewhere to land on hover without adding visual weight. */
.kr-trust__ring {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: ${layout.ringSize}px;
  height: ${layout.ringSize}px;
  margin-bottom: ${spacing.iconGap}px;
  border: ${layout.ringBorder}px solid ${color.ring};
  border-radius: 50%;
  color: ${color.icon};
  background: transparent;
  transition:
    color ${timing.hover}ms ${ease},
    border-color ${timing.hover}ms ${ease},
    background-color ${timing.hover}ms ${ease};
}
.kr-trust__item:hover .kr-trust__ring {
  color: ${color.iconHover};
  border-color: ${color.ringHover};
  background: ${color.ringHoverFill};
}

/* ── value ────────────────────────────────────────────── */
.kr-trust__value {
  margin: 0 0 ${spacing.valueGap}px;
  color: ${color.value};
  font-family: ${typography.valueFamily};
  font-size: ${typography.valueSize};
  font-weight: ${typography.valueWeight};
  letter-spacing: ${typography.valueTracking};
  line-height: ${typography.valueLeading};
  /* Stops the figure jittering in width while it counts up. */
  font-variant-numeric: tabular-nums;
}
/* A word such as "Dedicated" cannot carry numeral sizing. */
.kr-trust__value--word { font-size: ${typography.valueSizeWord}; }
/* Retained for any statistic still awaiting a real figure. */
.kr-trust__value--placeholder { color: ${color.valuePlaceholder}; }

.kr-trust__value-accent { color: ${color.valueAccent}; }

/* ── label ────────────────────────────────────────────── */
.kr-trust__label {
  margin: 0;
  max-width: 16ch;
  color: ${color.label};
  font-family: ${typography.labelFamily};
  font-size: ${typography.labelSize}px;
  font-weight: ${typography.labelWeight};
  letter-spacing: ${typography.labelTracking};
  line-height: ${typography.labelLeading};
  text-transform: uppercase;
}

/* ── responsive ───────────────────────────────────────── */
@media (max-width: ${layout.twoUpBelow}px) {
  .kr-trust {
    padding: ${spacing.sectionTopCompact}px 0 ${spacing.sectionBottomCompact}px;
  }
  .kr-trust__inner { padding: 0 ${spacing.gutterCompact}px; }

  .kr-trust__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: ${spacing.rowGapCompact}px;
  }
  /* In a 2-up grid only the right-hand column of each row takes a separator. */
  .kr-trust__item + .kr-trust__item::before,
  .kr-trust__item + .kr-trust__item::after { content: none; }
  .kr-trust__item:nth-child(even)::before,
  .kr-trust__item:nth-child(even)::after {
    content: "";
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
  }
  .kr-trust__item:nth-child(even)::before {
    width: ${layout.separatorWidth}px;
    height: ${layout.separatorHeight};
    background: ${color.separator};
  }
  .kr-trust__item:nth-child(even)::after {
    width: ${layout.separatorWidth}px;
    height: ${layout.separatorAccentHeight}px;
    background: ${color.separatorAccent};
  }
}

/* Stays 2x2 on the narrowest phones — only the scale comes down. */
@media (max-width: 520px) {
  .kr-trust__item { padding: 0 ${spacing.columnPaddingXCompact}px; }
  .kr-trust__ring {
    width: ${layout.ringSizeCompact}px;
    height: ${layout.ringSizeCompact}px;
    margin-bottom: ${spacing.iconGapCompact}px;
  }
  .kr-trust__label { font-size: ${typography.labelSizeCompact}px; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-trust__body {
    opacity: 1;
    transform: none;
    transition: none;
  }
  .kr-trust--in .kr-trust__item:hover .kr-trust__body { transform: none; }
  .kr-trust__ring { transition: none; }
}
`;

/** Without JavaScript the reveal class never lands, so show the columns. */
const noscriptCss = `
.kr-trust__body { opacity: 1; transform: none; }
`;

const template: TrustStripTemplate = {
  css,
  noscriptCss,
  rootClass: "kr-trust",
  timing,
  layout,
};

export default template;
